NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: 'Saul var dåen, og David var attkomen frå sigeren yver Amalek og hadde halde seg i Siklag tvo dagar.',
        2: 'Då hende det seg tridje dagen at han fekk sjå ein mann kom springande frå Sauls-lægret med sundrivne klæde og mold på hovudet. Då han kom burtåt David, fall han å gruve til jordi.',
        3: 'David spurde honom: «Kvar kjem du ifrå?» Han svara: «Eg hev kome meg undan frå Israels-lægret.»',
        4: '«Kor hev det gjenge?» spurde David, «seg meg det!» Han svara: «Folket rømde frå striden, mange av herfolket fall og døydde; Saul og Jonatan, son hans, er døydde og.»',
        5: 'David spurde sveinen som kom med tidendi: «Kor veit du at Saul og Jonatan, son hans, er daude?»',
        6: 'Då svara tidendsveinen: «Av eit hende høvde eg til å koma upp på Gilboafjellet og fekk sjå Saul studde seg til spjotet sitt, medan stridsvognerne og hestfolket sette inn på honom.',
        7: 'Han vende seg og såg meg, og ropte på meg, og eg svara ja;',
        8: 'Han spurde meg kven eg var; eg svara eg var ein amalekit.',
        9: 'So bad han meg: «Kom hit og drep meg! eg hev fenge baneridi, alt med det endå er liv i meg.»',
        10: 'Eg gjekk då fram og gav honom banestyngen. Eg skyna han kunde ikkje liva når han stupte. Eg tok so hovudgullet og ein armring av honom og bar hit til deg, herre!»',
        11: 'Då tok David og reiv sund klædi sine. Sameleis gjorde alle fylgjesveinarne hans.',
        12: 'Dei øya og gret og fasta alt til kvelden, for di Saul og Jonatan, son hans, og Herrens folk og Israels ætt hadde falle for sverd.',
        13: 'David spurde tiendsveinen: «Kvar er du ifrå?» Han svara: «Framandmanns son, amalekit er eg.»',
        14: 'Då sagde David med honom: «Kor våga du leggja hand på den som Herren hev salva, og drepe honom?»',
        15: 'Og David ropa på ein av sveinarne sine og sagde: «Hit, og hogg honom ned!» Og han gav honom banehogg.',
        16: '«Ditt blod kome yver ditt hovud,» sagde David; «din eigen munn vitna mot deg då du sagde: «Eg hev drepe honom som Herren hadde salva.»»',
        17: 'David kvad eit syrgjekvæde yver Saul og Jonatan, son hans',
        18: 'han baud dei skulde læra Juda-borni «Kvædet um bogen», det finst uppskrive i boki åt den rettvise:',
        19: 'Israels prydnad! drepen ligg du på haugarne dine! Ai ei! falne er kjemporne dine!',
        20: 'Gjet det ikkje i Gat! Lat deim ikkje gleda seg i Askalons-gatorne, so ikkje filistardøtter skal frygda seg og døtter av u-umskorne fegnast!',
        21: 'Og Gilboafjell! gjev dogg og regn ei må falla på dykk! og ingen åke gro med offergåvor! Der kasta kjemporne skjoldarne frå seg. Skjolden åt Saul - aldri med olje han meir vert smurd!',
        22: 'Av bøygde aldri Jonatans boge frå blod åt falne, frå feitta åt kjempor. Og aldri kom sverdet hans Saul kom att med ugjort!',
        23: 'Saul og Jonatan, elska og ljuvlege, uskiljande både i liv og daude! snøggare var dei enn ørnar, sterkare var dei enn løvor.',
        24: 'Israels døtter! Gråt for Saul, han som klædde dykk i yndeleg skarlak, han som prydde med gull dykkar klæde!',
        25: 'Ai ei! kjemporne fall i striden! Jonatan, drepen ligg han på haugarne dine!',
        26: 'Sårt eg deg syrgjer, Jonatan, bror min! Utifrå yndeleg var du for meg. Kjærleiken din kjærare var meg enn kvende-elsk.',
        27: 'Ai ei! at kjempor fall, og båe strids-sverdi øyddest!',
    },
    2: {
        1: 'Sidan spurde David Herren: «Skal eg draga upp til ein av byarne i Juda?» Herren svara ja. «Kvar helst?» spurde David. Herren svara: «Til Hebron.»',
        2: 'So drog David dit med båe konorne sine, Ahinoam frå Jizre’el og Abiga’il, kona åt Nabal frå Karmel.',
        3: 'David førde ogso fylgjesveinarne sine dit upp med huslydarne sine; og dei busette seg i byarne kringum Hebron.',
        4: 'Då kom Juda-folket dit og salva David til konge yver Juda-ætti. Då David fekk høyra at det var folket i Jabes i Gilead som hadde gravlagt Saul,',
        5: 'sende han bod til folket i Jabes i Gilead og sagde til deim: «Velsigna av Herren vere de som gjorde denne sælebotstenesta mot Saul, herren dykkar, at det gravlagde honom.',
        6: 'So vise då Herren dykk kjærleik og truskap! Sjølv vil eg løna dykk vel for de gode de gjorde.',
        7: 'Ver då urædde, og dugande karar! Saul, herren dykkar, er dåen; men meg hev Juda-ætti salva til konge yver seg.»',
        8: 'Abner Nersson, herhovdingen åt Saul, tok Isboset Saulsson og førde honom yver til Mahanajim,',
        9: 'og gjorde honom til konge yver Gilead, yver asuritarne og Jizre’el, yver Efraim, yver Benjamin, og yver heile Israel.',
        10: 'Isboset Saulsson var fyrti år gamall då han vart konge yver Israel, og han var konge i tvo år. Einast Juda-ætti fylgde David.',
        11: 'Og den tidi David var konge i Hebron yver Juda-ætti, var sju år og seks månader.',
        12: 'Abner Nersson drog ut frå Mahanajim til Gibeon med folket åt Isboset Saulsson.',
        13: 'Joab Serujason og Davids folk drog ut dei og. Og dei møttest ved Gibeontjørni. Der stogga dei på kvar si sida av tjørni.',
        14: 'Abner sagde til Joab: «Lat nokre av sveinarne våre koma fram og halda våpnleik for oss!» «Ja vel,» svara Joab.',
        15: 'Dei kom og møtte fram like mange i tal: tolv av Benjamin for Isboset Saulsson, og tolv av Davids folk.',
        16: 'Dei treiv kvarandre kring hovudet, og rende sverdi i sida på kvarandre, so dei fall alle i hop. Difor heitar den staden Sverdåkeren; han ligg attmed Gibeon.',
        17: 'Då vart det ein ovhard strid den dagen. Abner og Israels-mennerne vart slegne av Davids folk.',
        18: 'Tri søner av Seruja var med i striden: Joab, Ahisai og Asael. Asael var lettføtt som ei hind i heidi.',
        19: 'Og Asael forfylgde Abner, og veik korkje til høgre eller vinstre frå Abner.',
        20: 'Abner vende seg og sagde: «Er du Asael?» Han svara ja.',
        21: 'Abner sagde til honom: «Vend deg ei onnor leid, til høgre eller til vinstre! Tak på ein av sveinarne, og freista taka våpni hans!» Men Asael vilde ikkje slutta å elta honom.',
        22: 'Abner heldt endå fram og ropa til Asael: «Lat meg vera! elles lyt eg slå deg til jordi; og korleis skal eg då sjå Joab, bror din, i augo?»',
        23: 'Men han vilde ikkje slutta. Og so støytte Abner bakenden av spjotet inn i magen hans, so spjotet gjekk ut gjenom ryggen. Og det vart hans bane. Alle stogga når dei kom dit Asael fall og døydde.',
        24: 'Joab og Abisai forfylgde Abner. Men då soli gladde, var dei komne til Ammahaugen, beint imot Giah, på vegen til Gibeons-øydemarki.',
        25: 'Då samla dei seg, Benjamins-folki, attum Abner, so dei vart til ein flokk, og fylkte seg på toppen av ein og same haugen.',
        26: 'Abner ropa til Joab: «Skal då sverdet halda på og øyde i all æva? Skynar du ikkje at dette tek ein beisk ende? Kor lenge vil du drygja fyrr du byd folki dine slutta å elta brørne sine?»',
        27: 'Joab svara: «So sant Gud liver: hadde du ikkje tala, so vilde folket ha slutta å elta brørne sine alt frå morgonen.»',
        28: 'Joab let blåsa i luren. Alle stana, og slutta å elta Israel. Og so heldt dei upp å slåst.',
        29: 'Abner og kararne hans for yver heidi heile natti; dei gjekk yver Jordan og for gjenom heile Bitron, og kom so til Mahanajim.',
        30: 'Då Joab hadde slutta å elta Abner, samla han alt folket. Då sakna dei nittan mann av Davids folk, forutan Asael.',
        31: 'David folk hadde drepe tri hundrad og seksti mann av benjaminitarne og Abner-folket.',
        32: 'Dei tok Asael og gravlagde honom i farsgravi i Betlehem. So gjekk dei heile natti, Joab og mennerne hans, og kom ved dagsprett til Hebron.',
    },
    3: {
        1: 'Men krigen millom Sauls-ætti og Davids-ætti vart langdrjug. David vart stendigt sterkare; men Sauls-ætti minka i magt.',
        2: 'David fekk søner i Hebron: Eldste sonen, Amnon, fekk han med Ahinoam frå Jizre’el;',
        3: 'den andre, Kilab, med Abiga’il, kona åt Nabal frå Karmel; den tridje, Absalom, var son åt Ma’aka, som var dotter åt kong Talmai i Gesur,',
        4: 'den fjorde, Adonia, var son åt Haggit, den femte, Sefatja, son åt Abital;',
        5: 'den sette, Jitream, fekk han med Egla, kona si. Desse sønerne fekk David i Hebron.',
        6: 'So lenge no krigen varde millom Sauls-ætti og Davids-ætti, var Abner det trygge festet for Sauls-ætti.',
        7: 'Men no hadde Saul havt ei fylgjekona som heitte Rispa Ajadotter. Isboset spurde Abner: «Kvifor hev du halde deg med fylgjekona hans far?»',
        8: 'Dei ordi av Isboset gjorde Abner brennande harm: «Er eg ein hundehaus frå Juda?» sagde han; «nett medan eg gjer sælebot mot ætti åt Saul, far din, mot frendarne hans og venerne hans, medan eg vernar deg mot å falla i henderne på David, so kjem du med vondord for eit kvende skuld!',
        9: 'Gud late Abner bøta no og sidan, um eg ikkje heretter fer med David etter den eiden Herren hev svore honom:',
        10: 'å taka kongedømet frå Sauls-ætti og reisa upp Davids kongsstol yver både Israel og Juda, frå Dan til Be’erseba.»',
        11: 'Isboset orka ikkje svara Abner eit ord, so rædd vart han for honom.',
        12: 'Abner sende straks bod til David med dei ordi: «Kven eig landet?» og han lagde til: «Gjer samband med meg, so skal eg hjelpa deg å få heile Israel yver på di sida.»',
        13: 'Han svara: «Det er vel. Eg gjer samband med deg. Men ein ting krev eg av deg: du kjem ikkje fram for meg utan du hev med deg Mikal Saulsdotter når du kjem.»',
        14: 'David sende bod til Isboset Saulsson med dei ordi: «Gjev meg Mikal, kona mi, som eg fekk til brur for hundrad huvehold av filistarar!»',
        15: 'Isboset sende bod og henta henne frå Paltiel La’isson, mannen hennar.',
        16: 'Han fylgde gråtande etter henne heilt til Bahurim. Då tok Abner og truga honom: «Gakk heim att!» Og han gjekk heim.',
        17: 'Abner samrådde seg med dei øvste i Israel, og sagde: «Alt lenge siden hev de ynskt dykk David til konge.',
        18: 'So gjer no alvor av det! For Herren hev sagt med David: «Ved handi hans David, tenaren min, vil eg fria Israel, folket mitt, frå filistarane og frå alle uvenerne.»»',
        19: 'Abner talde fyre Benjamins-folket og. So gjekk Abner av stad, og vilde tala med David i Hebron um alt det Israel og Benjamins-ætti hadde funne fyre å svara.',
        20: 'Då Abner kom til David i Hebron med tjuge mann i fylgje, gjorde David eit gjestebod for Abner og fylgesveinarne hans.',
        21: 'Abner sagde med David: «Lat meg ganga av stad og stemna saman heile Israel ikring deg, herre konge, so dei kann gjera samband med deg, og du kann verta konge yver so mange som du ynskjer!» David sende Abner av stad, og han drog med full trygd.',
        22: 'Nett då kom Joab med Davids folk heim frå ei herjeferd, og hadde rikt herfang med seg. Abner var ikkje hjå David i Hebron då. David hadde sendt honom av stad med full trygd.',
        23: 'Då no Joab og heile heren hans kom heim, fekk han den tiendi: «Abner Nersson kom til kongen; og kongen let honom ganga av stad med full trygd!»',
        24: 'Joab gjekk til kongen og sagde: «Kva er det du hev gjort? Fyrst Abner kjem til deg, let du honom ganga av stad, so han fritt fær fara sin veg!',
        25: 'Du kjenner vel Abner Nersson? Han kjem berre og vil lokka eitkvart utor deg, og gjæta på deg når du fær ut og fær heim, og røkja etter alt du tek deg fyre!»',
        26: 'Då Joab kom ut frå David, sende han bod etter Abner; og sendemennerne førde honom attende frå Bor-Hassira; men David visste det ikkje.',
        27: 'Då Abner kom att til Hebron, tok Joab honom til sides i porten, og lest vilja tala med honom i einmæle. Der gav han honom banesår med ein styng i livet, til hemn for dråpet på Asael, bror hans.',
        28: 'Då David sidan spurde dette, sagde han: «Eg og kongedømet mitt er i all æva utan skuld for Herren i blodet hans Abner Nersson.',
        29: 'Må det koma yver Joab og heile ætti hans! Gjev det aldri må vanta i ætti åt Joab folk som hev flod eller spillsykja, som styd seg på krykkja eller fell for sverd, eller saknar mat!»',
        30: 'Joab og Abisai, bror hans, hadde myrdt Abner for dråpet på broren Asael i slaget ved Gibeon.',
        31: 'Men David baud Joab og heile fylgjet hans: «Riv sund klædi dykkar! Sveip sekkjer um dykk! Og øya og gråt yver Abner!» Og kong David fylgde sjølv etter likbåra.',
        32: 'Abner vart gravlagd i Hebron. Og kongen sette i og gret ved gravi hans Abner; og heile folket gret.',
        33: 'David kvad eit syrgjekvede yver Abner: «Laut du Abner døy som ein dåre.',
        34: 'Henderne dine batt dei ikkje, føterne dine fjetra dei ikkje! Nidingsdråp er det, so som du vart drepen!» Då gret alt folket endå meir yver honom.',
        35: 'Alt folket kom og talde David til å eta eitkvart fyrr dagen leid. Men David svor og sagde: «Gud late meg bøta både no og sidan, um eg smakar matbiten eller noko som helst fyre soleglad!»',
        36: 'Heile folket merkte seg ordi og lika det godt. I det heile lika folket godt alt det kongen gjorde.',
        37: 'Heile folket og heile Israel skyna den dagen at kongen ingi skuld hadde i dråpet på Abner Nersson.',
        38: 'Kongen sagde med tenararne sine: «Veit de det er ein hovding og stor mann som er fallen i dag i Israel?',
        39: 'Eg er endå veik, endå eg er salva til konge. Og desse kararne, Seruja-sønerne, er sterkare enn eg. Herren løne nidingen etter nidingsverket hans!»',
    },
    4: {
        1: 'Då Saulssonen spurde at Abner var dåen i Hebron, miste han reint modet, og heile Israel vart forstøkt.',
        2: 'Saulssonen hadde hjå seg tvo herhovdingar for herjeferderne sine. Ba’ana heitte ein, og Rekab heitte hin, sønerne åt Rimmon frå Be’erot, av Benjamins-ætti; for Be’erot vart og rekna med til Benjamin;',
        3: 'folket i Be’erot hadde rømt til Gittajim, og budde sidan der som utlendingar, alt til no.',
        4: 'Jonatan Saulsson hadde ein son som var lamen på båe føterne. Fem år gamall var han då tidendi frå Jizre’el kom um Saul og Jonatan. Barnfostra tok og rømde med honom. Men i hurten og sturten datt han; og so vart han lamen. Mefiboset heitte han.',
        5: 'No gjekk Rekab og Ba’ana, sønerne åt Rimmon frå Be’erot, av stad og kom høgstedags til huset åt Isboset medan han låg og kvilde middag.',
        6: 'Dei lest henta kveite, kom seg soleis inn i huset, og såra honom i livet. Og so kom dei seg undan både Rekab og Ba’ana, bror hans.',
        7: 'Det var medan han låg i sengi i kammerset at dei kom inn i huset og gav honom banesår. Dei hogg av hovudet hans, og tok det med seg, gjekk yver heidi heile natti,',
        8: 'førde hovudet hans Isboset til David i Hebron, og sagde med kongen: «Her er hovudet åt uvenen din, Isboset Saulsson, han som vilde taka livet ditt. Herren hev i dag gjeve deg, herre konge, hemn yver Saul og ætti hans.»',
        9: 'David svara Rekab og Ba’ana, bror hans, sønerne åt Rimmon frå Be’erot: «So sant Herren liver som hev frelst meg ut frå all fåre:',
        10: 'den som kom med tidendi: «Saul er dåen!» og meintest koma med fagnadbod til meg, honom let eg gripa og drepa i Siklag, han som eg skulde gjeve løn for fagnadbod.',
        11: 'Men når nidingar myrder ein rettvis mann i heimen hans, i sengi - kor mykje meir må eg ikkje krevja blodet hans av dykkar hender, og rydja dykk burt frå jordi!»',
        12: 'David baud sveinarne sine drepa deim, og hogga av deim hender og føter og hengje deim upp attmed Hebrontjørni. Hovudet hans Isboset tok dei og gravlagde i Abners grav i Hebron.',
    },
    5: {
        1: 'Då kom alle Israels ætter til David i Hebron, og tala soleis: «Du veit me og du er same folket.',
        2: 'Alt lenge sidan, med Saul var kongen vår, so var du føraren for Israel. Og med deg hev Herren sagt: «Du skal vera hyrding for Israel, folket mitt! du skal vera fyrste yver Israel!»»',
        3: 'Då alle dei øvste i Israel var komne til Hebron, til kongen, gjorde kong David samband med deim i Hebron for Herrens åsyn. Og dei salva David til konge yver Israel.',
        4: 'Tretti år var David då han vart konge. Og han var konge i fyrti år.',
        5: 'I Hebron var han konge yver Juda i sju år og seks månader. I Jerusalem var han konge i tri og tretti år yver heile Israel og Juda.',
        6: 'Kongen drog upp til Jerusalem med heren sin mot jebusitarne, som budde der i landet. Dei sagde då til David: «Hit inn vinn du ikkje koma! Jamvel blinde og lame folk kann driva deg burt berre med dei ordi: Hit kjem David ikkje!»',
        7: 'David tok like vel Sionsborgi. Den borgi vart Davidsbyen.',
        8: 'David gav den dagsordren: «Kvar ein som slær jebusitarne, lat honom ganga upp til vatsleidingi, og slå desse blinde og lame som ber David imot!» Difor plar dei segja: «Blind og lam kjem ikkje inn i huset.»',
        9: 'David tok bustad der på borgi og kalla henne Davidsbyen. David bygde byen rundt ikring frå Millo og innetter.',
        10: 'Davids velde auka stødt og stendigt. Og Herren, allhers Gud, var med honom.',
        11: 'Kong Hiram i Tyrus sende folk til David med cedertre og timbremenner og steinhoggarar. Dei bygde eit hus for David.',
        12: 'Og David skyna at Herren hadde grunnfest kongedømet hans yver Israel, og lyft kongedømet hans upp til æra for Israel, folket sitt, skuld.',
        13: 'David tok seg endå fleire fylgjekonor og konor frå Jerusalem, etter han var komen dit frå Hebron. Og David fekk endå fleire søner og døtter.',
        14: 'Dei sønerne han fekk i Jerusalem heitte: Sammua, Sobab, Natan, Salomo,',
        15: 'Jibhar, Elisua, Nefeg, Jafia,',
        16: 'Elisama, Eljada og Elifelet.',
        17: 'Då filistarane frette at David var salva til konge yver Israel, drog alle filistarane upp og søkte åt honom. Då David spurde det, drog han ned til borgi.',
        18: 'Filistarane kom og spreidde seg utyver i Refa’imsdalen.',
        19: 'Då gjorde David det spursmålet til Herren: «Skal eg draga upp mot filistarane? Vil du gjeva deim i mi hand?» Herren svara David: «Drag upp, eg vil gjeva filistarane i di hand.»',
        20: 'David kom til Ba’al-Perasim. Og der vann David yver deim. Då sagde han: «Herren hev brote igjenom uvenerne mine, liksom vatn bryt igjenom.» Det er difor staden hev fenge namnet Ba’al-Perasim.',
        21: 'Dei let etter seg gudebilæti sine, og David og folki hans tok deim.',
        22: 'Endå ein gong drog filistarane upp og spreidde seg utyver i Refa’imsdalen.',
        23: 'Då David spurde Herren, svara han: «Drag ikkje mot deim! Kringset deim attanfrå, so du fell yver deim frå den staden der bakatrei stend.',
        24: 'So snart du høyrer ljoden av stig i topparne på bakatrei, so må du springa fram. For då dreg Herren ut framfyre deg og vinn yver filistarheren!»',
        25: 'David gjorde som Herren baud; og han slo filistarane og forfylgde deim frå Geba heilt fram til Gezer.',
    },
    6: {
        1: 'Endå eingong stemnde David saman alt det utvalde mannskapet i Israel: tretti tusund mann.',
        2: 'Og David gav seg på veg, og drog ut med alt sitt folk frå Ba’ale-Juda, og førde derifrå Guds kista, som heiter etter Herren, allhers drott, han som tronar på kerubarne.',
        3: 'Dei sette Guds kista på ei ny vogn og førde henne frå Abinadabs hus på haugen. Og Uzza og Ahjo Abinadabs-søner køyrde den nye vogni.',
        4: 'Soleis førde dei Guds kista burt frå Abinadabs hus på haugen, med di dei fylgde henne, og Ahjo gjekk fyre kista.',
        5: 'David og heile Israels-ætti leika for Herren, til alle slag spel av cypresstre, til cithrar, harpor, trummor, bjøllor og cymblar.',
        6: 'Då dei kom burtimot treskjestaden åt Nakon, tok Uzza tak med henderne i Guds kista og heldt fast i henne, av di uksarne snåva.',
        7: 'Då loga Herrens harm upp mot Uzza. Og Gud slo honom for det brotet skuld. Og han fekk sin bane der attmed Guds kista.',
        8: 'David vart ille ved av di Herren øydelagde Uzza. Og den staden heite Peres-Uzza den dag i dag.',
        9: 'Men David vart so rædd for Herren den dagen, at han sagde: «Kor kann eg våga føra Herrens kista upp til meg!»',
        10: 'Difor vilde ikkje David flytja Herrens kista upp til Davidsbyen, men let deim setja henne inn i huset åt gatiten Obed-Edom.',
        11: 'So stod Herrens kista der i tri månader. Og Herren velsigna Obed-Edom og heile hans hus.',
        12: 'Då kong David spurde at Herren velsigna huset åt Obed-Edom og all hans eigedom for Guds kista skuld, drog David av stad og flutta Guds kista derifrå og upp til Davidsbyen med stor fagnad.',
        13: 'Då dei som bar Herrens kista, hadde gjenge seks stig, ofra han ein ukse og ein gjødkalv.',
        14: 'David sjølv dansa av all magt framfor Herren i ein messehakel av lin.',
        15: 'Soleis henta David og heile Israels-ætti Herrens kista dit upp med fagnadrop og lurljod.',
        16: 'Då Herrens kista kom inn i Davidsbyen, stod Mikal Saulsdotter og såg ut igjenom vindauga. Då ho fekk sjå kong David sprang og dansa framfor Herren, då fekk ho vanvyrdnad for honom i sitt hjarta.',
        17: 'Då dei hadde ført Herrens kista upp, sette dei henne på sin stad midt i det tjeldet som David hadde reist åt henne. David ofra brennoffer og takkoffer for Herren.',
        18: 'Og då han var ferdig med desse ofringarne, velsigna han folket i namnet åt Herren, allhers drott.',
        19: 'Deretter skifte han ut åt heile folket, åt heile Israels-ålmugen, både åt kar og kvende, ei hellekaka, eit stykke kjøt og ei rosinkaka til manns. So gjekk heile folket heim kvar til seg.',
        20: 'Men då David kom heim og helsa husfolki sine, gjekk Mikal Saulsdotter til møtes med honom og sagde: «Kor måtte ikkje Israels konge kjenna seg høgvyrd i dag, med han i dag hev nækt seg framfor tenestgjentorne åt tenarane sine, soleis som skamlaust folk plar nækja seg.»',
        21: 'David svara Mikal: «For Herrens åsyn hev eg dansa, han som valde meg ut framfor far din og framfor heile hans ætt, og sette meg til fyrste for Israel, Herrens folk. For Herrens åsyn var det eg dansa,',
        22: 'og småminka meg meir, og verta ring i mine augo. Men hjå dei tenestgjentorne du nemnde, hjå deim skal eg verta høgvyrd.»',
        23: 'Mikal Saulsdotter vart verande barnlaus alt til sin døyande dag.',
    },
    7: {
        1: 'Ein gong kongen sat i huset sitt, og Herren hadde unnt honom fred for alle uvenerne sine rundt ikring,',
        2: 'so sagde han med profeten Natan: «Sjå her bur eg i eit hus av cedertre; men Guds kista bur i eit tjeld.»',
        3: 'Natan svara kongen: «Gjer du alt det du finn fyre! For Herren er med deg!»',
        4: 'Men natti etterpå kom Herrens ord til Natan soleis:',
        5: '«Gakk av stad og seg med David, tenaren min: «So segjer Herren: Etlar du byggja hus der eg skal bu?',
        6: 'Eg hev då ikkje butt i noko hus heilt frå den tid eg førde Israels-borni upp frå Egyptarland alt til i dag, men hev flutt rundt i eit tjeld og i ei bud.',
        7: 'All den tidi eg flutte rundt med Israels-borni - hev eg noko sinn nemnt eit einaste ord um det med nokon av domarane i Israel som eg bad vakta Israel, folket mitt, og sagt: «Kvifor byggjer de ikkje eit hus av cedertre åt meg?»»',
        8: 'Og no skal du segja so med David, tenaren min: «So segjer Herren, allhers drott: Eg henta deg frå beitemarki der du fylgde småfeet, og sette deg til fyrste yver Israel, folket mitt;',
        9: 'eg var med deg på alle dine vegar, eg rudde ut alle dine uvener; og eg vil gjeva deg eit namn so stort som dei største på jordi;',
        10: 'og Israel, folket mitt, gjev eg ein bustad; der set eg deim ned, der skal dei få bu og aldri verta uroa meir; og aldri skal nidingar kua deim meir, so som i gamle dagar,',
        11: 'då eg sette domarar yver Israel, folket mitt; eg gjev deg fred for alle dine uvener. Og Herren forkynner deg at Herren vil byggja hus åt deg.',
        12: 'Når æva di er all, og du fær kvila hjå dine feder, so vil eg reisa upp avkjømet ditt som kjem etter deg og gjeng ut frå deg; hans kongedøme vil eg grunnfesta.',
        13: 'Han skal byggja hus åt meg, hans kongsstol vil eg grunnfesta til æveleg tid.',
        14: 'Eg vil vera far for honom, han skal vera son min: gjer han noko gale, so vil eg refsa honom med manneris, med ulukkar som manneborn kann røyna;',
        15: 'men mi miskunn skal aldri vika frå honom, so som ho veik frå Saul, då eg let honom vika undan for deg.',
        16: 'Stød skal ætti di standa, traust og trygt ditt kongedøme i all æva for di åsyn; ja stødug skal din kongsstol standa i all æva.»»',
        17: 'Natan tala alle desse ordi til David og sagde honom heile denne syni.',
        18: 'Då gjekk kong David inn og sette seg ned framfor Herrens åsyn og sagde: «Kven er eg, Herre, Herre! og kva er huset mitt, at du hev ført meg hit?',
        19: 'Og endå er det for lite i dine augo, Herre, Herre! Du gjev meg lovnader um huset åt tenaren din langt fram i tidi. På mannevis talar du um dette, Herre, Herre!',
        20: 'Kva hev no David meir å mæla med deg? Du kjenner tenaren din, Herre, Herre!',
        21: 'For ditt ord skuld, og etter eigen hug, gjer du alt dette og kunngjer dette underverk for tenaren din.',
        22: 'Difor er du stor, du Herre Gud. Ingen er som du! Forutan deg er det ingen Gud, etter alt me hev høyrt gjete med øyro våre.',
        23: 'Kvar finst på jordi noko folk maken til folket ditt, til Israel, som Gud sjølv gjekk av og løyste til sin eigen lyd, til eit frægdarnamn åt seg og gjorde so store gjerningar for dykk og agelege verk med landet ditt, for folket ditt, det som du sjølv løyste ut åt deg frå Egyptarland, frå heidningefolk og deira gudar.',
        24: 'Israels-folket hev du grunnfest til ditt folk i all æva. Du, Herre, vart deira Gud!»',
        25: 'So lat no lovnaden din, Herre Gud, um tenaren din og huset hans få standa stødt i alder og i æva! Gjer som du hev sagt!',
        26: 'Då skal namnet ditt verta stort i all æva og lyda so: «Herren, allhers drott, er Gud yver Israel.» Og huset åt din tenar David skal standa stødt for di åsyn.',
        27: 'Du, Herre, allhers drott, Israels Gud! Sjølv hev du kunngjort for tenaren din: «Eg byggjar hus åt deg.» Difor hev tenaren din teke seg mod til å bera denne bøni fram for deg.',
        28: 'Og no, Herre, Herre! Du er Gud, og dine ord er sætande, og du hev lova tenaren din alt dette gode.',
        29: 'So gjer no vel, velsigna huset mitt so det må standa i all æva for di åsyn! Ja, du hev sagt det, Herre, Herre! Med di velsigning skal huset åt tenaren velsignast til æveleg tid.',
    },
    8: {
        1: 'Ei tid deretter vann David yver filistarane og lagde deim under seg. David fekk dermed teke taumarne yver hovudstaden utor henderne på filistarne.',
        2: 'So vann han yver moabitarne; deim mælte han med ei snor, det vil segja: han let deim leggja seg ned på marki, og mælte med tvo snorlengder deim som skulde lata livet, og med ei snorlengd deim som skulde liva. Moabitarne vart David undergjevne og laut leggja skatt.',
        3: 'Dessutan vann David yver Soba-kongen Hadadezer Rehobsson, då han for i herferd og vilde tøygja magti si alt til Storelvi.',
        4: 'David tok syttan hundrad hestfolk og tjuge tusund fotfolk. Og David let skjera sund hasarne på alle vognhestarne, sparde berre hundrad hestar.',
        5: 'Då Syria-folket frå Damaskus kom Soba-kongen Hadadezer til hjelp, slo David tvo og tjuge tusund Syria-menner.',
        6: 'David sette hervakter yver syrarane i Damaskus, og Syria-folket vart David undergjevne og laut leggja skatt. Soleis gav Herren David siger kvar helst han for fram.',
        7: 'David tok dei gylte skjoldarne som Hadadezer-folki hadde bore, og førde til Jerusalem.',
        8: 'Og frå Hadadezer-byarne Betah og Berotai tok kong David store mengder av kopar.',
        9: 'Då Hamat-kongen To’i frette at David hadde vunne yver heile Hadadezer-heren,',
        10: 'sende han Joram, son sin, til kong David til å helsa på honom og ynskja honom til lukka med krigen mot Hadadezer og med sigeren yver honom - for Hadadeser hadde jamt ført krig mot To’i - og han hadde med seg kostnadting av sylv, av gull og av kopar.',
        11: 'Kong David vigde deim og til Herren, like eins som han hadde gjort med sylvet og gullet frå folki han hadde lagt under seg:',
        12: 'frå syrarane, moabitarne, ammonitarne, filistarane og amalekitarne; like eins med herfanget frå Soba-kongen Hadadezer Rehobsson.',
        13: 'Då David kom heim etter sigeren yver syrarane, auka han frægdi si med di han slo attan tusund mann i Saltdalen.',
        14: 'Han sette hervakter yver Edom; i heile Edomlandet sette han vakter; og alle edomitarne vart David undergjevne. Soleis gav Herren David siger kvar helst han drog fram.',
        15: 'David var no konge yver heile Israel. Og David skipa lov og rett for heile folket sitt.',
        16: 'Joab Serujason var øvste herhovding. Josafat Ahiludsson var kanslar.',
        17: 'Sadok Ahitubsson og Ahimelek Abjatarsson var prestar. Og Seraja var riksskrivar.',
        18: 'Benaja Jojadason var hovding yver livvakti. Sønerne åt David var prestar.',
    },
    9: {
        1: 'David spurte: «Finst det endå att nokon av Sauls hus? Eg vil gjera sælebot mot honom for Jonatans skuld.»',
        2: 'Sauls hus åtte ein tenar, Siba heitte han; honom kalla dei til David. Kongen spurde honom: «Er du Siba?» Han svara: «Ja, tenaren din er det.»',
        3: 'Kongen spurde: «Finst det endå att nokon av Sauls hus, som eg kann gjera Guds sælebot mot?» Siba svara kongen: «Det finst endå att ein son åt Jonatan, han er lam på båe føterne.»',
        4: 'Kongen spurde: «Kvar er han?» Siba svara: «Han held seg no hjå Makir Ammielsson i Lo-Debar.»',
        5: 'Kong David sende då bod og henta honom frå Lo-Debar, frå heimen åt Makir Ammielsson.',
        6: 'Då Mefiboset, son åt Jonatan Saulsson, kom til David, fall han å gruve og bøygde seg. David sagde: «Mefiboset!» Han svara: «Ja, her er tenaren din.»',
        7: 'David trøysta honom: «Ver hugheil; eg vil gjera sælebot mot deg for skuld Jonatan, far din. Eg gjev deg att all jordeigedomen åt Saul, farfar din. Og du skal allstødt eta ved mitt bord.»',
        8: 'Då bøygde han seg og sagde: «Kva er eg, tenaren din, at du vendar deg til ein daud hund som meg?»',
        9: 'Kongen kalla på Siba, sveinen åt Saul, og gav honom det bodet: «Alt det Saul og ætti hans åtte, gjev eg åt son til herren din.',
        10: 'Du og sønerne dine og tenarane dine skal dyrka og hausta eigedomen hans; og det skal vera til kost og tæring levemåte åt son til herren din. Men sjølv skal Mefiboset, son åt herren din, stødt eta ved mitt bord.» Siba hadde femtan søner og tjuge tenarar.',
        11: 'Han svara kongen: «Alt det du, herre konge, byd tenaren din, det skal tenaren din gjera.» «Og Mefiboset skal eta ved mitt bord som ein av kongssønerne.»',
        12: 'Mefiboset hadde ein liten son, Mika heitte han. Alle som budde i huset åt Siba, vart tenarar for Mefiboset.',
        13: 'Men sjølv budde Mefiboset i Jerusalem, då han stødt åt ved kongens bord. Han var lam på båe føterne.',
    },
    10: {
        1: 'Det hende seg deretter at ammonitarkongen døydde. Og Hanun, son hans, vart konge etter honom.',
        2: 'Då sagde David: «Eg vil syna Hanun Nahasson venskap, liksom far hans synte meg venskap.» David sende nokre av tenarane sine til å trøysta honom i sorgi yver faren. Tenarane åt David kom til Ammonitarlandet.',
        3: 'Då sagde ammonitarfyrstarne til Hanun, herren sin: «Trur du det er til heider for far din at David hev sendt trøystarar til deg? Å nei, David hev sendt tenarane til deg berre for di han vil granska byen og njosna, og sidan gjera enden på honom.»',
        4: 'So tok Hanun tenarane hans David og let raka av deim halve skjegget og skjera klædi deira midt yver like upp til seten, og sende deim heim soleis.',
        5: 'Då David frette det, sende han folk til møtes med deim, og kongen let segja med deim: «Stana i Jeriko til dess skjegget hev vakse ut på dykk, so kann de koma heim att!» For mennerne hadde vorte øgjeleg svivyrde.',
        6: 'Då no ammonitarne skyna dei hadde gjort David hatig på seg, sende dei bod og leigde tjuge tusund mann fotfolk, syrarar frå Bet-Rehob og syrarar frå Soba, eit tusund mann hjå kong Ma’aka, og tolv tusund av mannskapet åt Tob.',
        7: 'Då David høyrde gjete det, sende han Joab med heile heren, det vil segja dei djervaste stridsmennerne.',
        8: 'Ammonitarne drog ut og fylkte seg framfor byporten, medan syrarane frå Soba og Rehob og Tob-folket og Ma’aka-folket stod for seg sjølve på opi mark.',
        9: 'Då Joab gådde han laut vera budd på åtak både framme og bak, gjorde han eit utval millom dei utvalde Israels-hermennerne, og fylkte deim mot syrarane.',
        10: 'Resten av folket let han åt Abisai, bror sin, som so fylkte deim beint imot ammonitarne.',
        11: 'Og han sagde: «Um syrarane vinn på meg, so kjem du meg til hjelp. Og um ammonitarne vinn på deg, so skal eg koma og hjelpa deg.',
        12: 'Ver sterk! Lat oss syna oss sterke i striden for folket vårt og for byarne åt vår Gud! So fær Herren gjera det han tykkjer best.',
        13: 'Joab drog fram med mannskapet sitt og stridde mot syrarane, og dei rømde for honom.',
        14: 'Då ammonitarne såg at syrarane rømde, so rømde dei og for Abisai, og sprang inn i byen. Og Joab drog burt frå ammonitarne og kom heim att til Jerusalem.',
        15: 'Då syrarane såg at dei var slegne av Israel, samla dei seg i hop.',
        16: 'Hadadezer baud ut dei syrarane som budde på hi sida Storelvi. Og dei kom til Helam, med Sobak, herhovdingen åt Hadadezer, til førar.',
        17: 'Då David spurde dette, stemnde han saman heile Israel, gjekk yver Jordan og kom til Helam. Syrarane fylkte seg og gjorde åtak på David og slost med honom.',
        18: 'Men syrarane rømde for Israel, og David hogg ned sju hundrad krigshestar og fyrti tusund hestfolk av syrarheren; og herhovdingen Sobak fekk banehogg der.',
        19: 'Då alle lydkongarne under Hadadezer såg dei var slegne av Israel, gjorde dei fred med Israel og vart tenarane deira. So våga ikkje syrarane hjelpa ammonitarne meir.»',
    },
    11: {
        1: 'Det hende seg året etter, den tid då kongarne plar fara i herferd, då sende David Joab av stad, og alle herhovdingarne som var under honom og heile Israel, og dei herja Ammonitarlandet og kringsette Rabba. Sjølv heldt David seg heime i Jerusalem.',
        2: 'No bar det so til ein dag ved kveldstid David reis upp frå kvila si og gjekk og dreiv på taket på kongshalli, at han såg frå taket ei kona som lauga seg. Kona var ovleg væn å sjå til.',
        3: 'David let spyrja etter kven kona var. Han fekk til svar: «Det er Batseba Eliamsdotter, kona åt hetiten Uria.»',
        4: 'David sende nokre folk og let henta henne. Ho kom upp, og han låg med henne. Ho hadde nett helga seg etter ho hadde vore urein. Og so for ho heim att.',
        5: 'Kona vart med barn. Ho sende bod og melde David at ho var med barn.',
        6: 'David sende då det bodet til Joab: «Send hit hetiten Uria!» Joab sende Uria til David.',
        7: 'Då Uria kom inn til honom, spurde David korleis Joab og heren hadde det, og kor det gjekk i krigen.',
        8: 'So sagde David med Uria: «No kann du ganga heim og lauga føterne dine.» Då Uria gjekk frå kongshalli, fylgde ei kongsgåva etter honom.',
        9: 'Men Uria lagde seg ved inngangen til kongshalli saman med alle kongstenarane; han gjekk ikkje heim.',
        10: 'David fekk vita at Uria ikkje var gjengen heim. Då sagde David med Uria: «Du kjem då frå ei utferd! Kvifor gjeng du ikkje heim?»',
        11: 'Uria svara: «Kista og Israel og Juda bur no i buder; Joab, herren min, og folket hans ligg i læger ute på marki. Og so skulde eg ganga heim og eta og drikka og liggja med kona mi? So sant Herren liver, og so sant du liver: dette gjer eg ikkje!»',
        12: 'Då sagde David med Uria: «Stana her i dag og! So vil eg i morgon senda deg av stad.» Uria stana i Jerusalem den dagen og næste dag.',
        13: 'David bad honom til seg, til å eta og drikka med seg; og han drakk honom drukken. Men um kvelden gjekk han av og lagde seg til kvile med kongstenarane; heim gjekk han ikkje.',
        14: 'Morgonen etter skreiv David eit brev til Joab og sende det med Uria.',
        15: 'I brevet skreiv han: «Set Uria lengst framme, der som striden er hardast. Røm so undan frå honom, so han fær banehogg!»',
        16: 'Joab heldt på og kringsette byen. Då sette han Uria på den staden, der han visste han møtte dei djervaste kararne.',
        17: 'Byfolket gjorde utfall og slost med Joab. Det fall då nokre av folket, av mannskapet åt David; hetiten Uria fekk og banen sin der.',
        18: 'Joab sende melding til David um korleis det hadde gjenge i slaget.',
        19: 'Og han gav sendemannen den fyresegni: «Når du er ferdig med å melda kongen alt um striden,',
        20: 'og so harmen kjem upp hjå kongen, og han spør deg: «Kvifor kom de so nær byen i striden? de måtte då vita at dei vilde skjota på dykk ovantil frå muren!',
        21: 'Kven var det som vart banen hans Abimelek Jerubbesetsson? Ei kona som kasta ein kvernstein i hovudet på honom ovanfrå muren! Det vart banen hans, der i Tebes! Kvifor kom de so nær muren?» - so skal du fortelja: «Tenaren din, hetiten Uria, fekk og banen sin.»»',
        22: 'Mannen gjekk og melde David alt det Joab hadde bode honom.',
        23: 'Mannen fortalde for David: «Kararne gjekk hardt på og drog ut mot oss i opi mark. Men me slo deim attende til byporten.',
        24: 'Då skaut bogeskyttarane på tenarane dine ovanfrå muren, so nokre av kongsmennerne dine fekk sin bane; tenaren din, hetiten Uria, fekk og sin bane der.»',
        25: 'David svara sendemannen: «So skal du svara Joab: «Gjer deg inkje ilt av dette! sverdet øyder so ein, so hin! Berre gakk på byen med større styrke, og riv honom ned til grunns!» Styrk hugen hans med dei ordi!»',
        26: 'Då kona hans Uria spurde at mannen hennar var fallen, øya og gret ho yver husbonden sin.',
        27: 'Då syrgjetidi var ute, sende David bod og let henta henne heim til seg. Ho vart kona hans, og ho åtte ein son. Men det David hadde gjort, var ilt i Herrens augo.',
    },
    12: {
        1: 'Og Herren sende Natan til David. Då han kom inn til honom, sagde han med honom: «Det var tvo menner i ein by; den eine var rik, og den andre var fatig.',
        2: 'Rikmannen åtte bufe og smale i rikleg mengd.',
        3: 'Fatigmannen åtte inkje anna enn eit lite saulamb, som han hadde kjøpt og ale upp, og som voks upp inne hjå honom og sønerne hans, i lag med deim; det åt av brødbiten hans og drakk av staupet hans, og låg i fanget hans og var som ei dotter for honom.',
        4: 'So kom ein vegfarande mann til rikmannen. Då timdest han ikkje taka av sine eigne sauer eller naut sine og laga til åt ferdamannen som var komen til honom, men tok saulambet åt fatigmannen og laga til åt mannen som var komen til honom.»',
        5: 'Då loga harmen veldug upp i David mot mannen, og han sagde til Natan: «So sant Herren liver: den mannen som det hev gjort, skal lata livet;',
        6: 'og saulambet skal han bøta firfaldt, for di han for soleis fram og var so hjartelaus.»',
        7: 'Natan svara: «Du er mannen. So segjer Herren, Israels Gud: «Eg salva deg til konge yver Israel; eg frelste deg or Sauls hand.',
        8: 'Eg gav deg huset åt herren din, og konorne åt herren din lagde eg i ditt fang. Eg sette deg yver Israels hus og Judas hus. Og var det for lite, so hadde eg gjeve deg endå meir både av eitt og hitt.',
        9: 'Kvifor hev du då vanvyrdt Herrens ord, og gjort det som er ilt i hans augo? Hetiten Uria hev du drepe med sverd, og kona hans hev du teke til kona åt deg sjølv! Honom myrde du med ammonitarsverd.',
        10: 'Difor skal no sverdet aldri vika frå ditt hus, av di du vanvyrde meg og tok kona åt hetiten Uria til kona åt deg sjølv.»',
        11: 'So segjer Herren: «Sjå, eg let ulukke koma yver deg frå ditt eige hus. Konorne dine tek eg burt frå augo dine og gjev deim åt ein annan, so han ligg med konorne dine midt på ljose dagen.',
        12: 'Du let det henda i løyndom; eg let dette henda midt på ljose dagen, so heile Israel er vitne til det.»»',
        13: 'David svara Natan: «Synda hev eg mot Herren.» Natan sagde til David: «So hev Herren ogso ettergjeve deg skuldi di; du skal ikkje døy.',
        14: 'Men av di du hev fenge Herrens fiendar til å spotta honom for denne sak skuld, so skal heller ikkje den sonen du hev fenge vera liv lage.»',
        15: 'So gjekk Natan heim. Men Herren søkte med sott det barnet David hadde fenge med kona hans Uria.',
        16: 'David spurde Gud for barnet. Og David fasta. Og når han kom heim og skulde leggja seg um natti, lagde han seg på golvet.',
        17: 'Dei øvste tenarane hans gjekk upp til honom og freista reisa honom upp frå golvet. Men han vilde ikkje. Heller ikkje heldt han måltid i lag med deim.',
        18: 'Sjuande dagen døydde barnet. Då våga ikkje tenarane åt David melda honom at barnet hadde slokna. Dei tenkte: «Tala me til honom med barnet var i live, so lydde han ikkje på oss; kor kann me då melda honom at barnet hev slokna? Han kunde gjera ei ulukka!»',
        19: 'Men David gådde at tenarane kviskra saman, og han skyna barnet var dåe. David spurde tenarane: «Hev barnet slokna?» Dei svara ja.',
        20: 'Då reis David upp frå golvet, vaska seg, salva seg, skifte klæde, gjekk inn i Herrens hus og kasta seg ned for honom. Og då han kom heim, bad han um mat. Dei fram mat åt honom, og han tok til å eta.',
        21: 'Då spurde tenarane honom: «Korleis heng dette i hop? So lenge barnet var i live, fasta du og gret for det; men når barnet hev slokna, ris du upp og held måltid!»',
        22: 'Han svara: «So lenge barnet var i live, fasta eg og gret. Eg tenkte: «Kven veit? kann henda Herren vil miskunna meg og lata barnet liva!»',
        23: 'Men kvifor skulde eg fasta no det er dåe? Kann eg få det att meir? Eg skal fara til honom. Men han kjem ikkje att til meg.»',
        24: 'David trøysta Batseba, kona si. Han budde hjå henne og låg med henne. Ho åtte ein son, som han gav namnet Salomo. Honom hadde Herren kjær.',
        25: 'Han sende bod med profeten Natan. Og han gav honom namnet Jedidja for Herrens skuld.',
        26: 'Joab gjorde åtak på hovudstaden Rabba i Ammonitarlandet, og hertok byen.',
        27: 'So sende Joab bod til David og melde: «Eg hev gjort åtak på Rabba og hev teke vats-byen.',
        28: 'Stemn no i hop resten av folket! Kringset og tak byen, so det ikkje skal heitast at eg hev teke byen, og fær ordet for det!»',
        29: 'David stemnde då saman alt herfolket, drog til Rabba, gjorde åtak og tok byen.',
        30: 'Han tok kongekruna frå hovudet på kongen. Ho var av gull og vog vel tvo vågar og var prydd med ein glimestein. Ho vart no sett på Davids hovud. Eit veldugt herfang førde han heim frå byen.',
        31: 'Folket i byen slæpte han burt, og sette til arbeid ved sagbruki, med treskjevalsorne av jarn og med jarnøksarne, og let deim træla ved tiglomnarne. Soleis gjorde han med alle ammonitarne. So snudde David med alt folket heim att til Jerusalem.',
    },
    13: {
        1: 'Sidan hende denne tilburden: Absalom Davidsson hadde ei væn syster som heitte Tamar, og Amnon Davidsson lagde hugen til henne.',
        2: 'Ja Ammon pintest so, at han vart heiltupp sjuk av lyst til syster si; for ho var møy; og Ammon øygnde ingen utveg til å gjera henne noko.',
        3: 'Amnon hadde ein ven, som heitte Jonadab, son til Simea, bror åt David. Jonadab var ein utkropen kar.',
        4: 'Han spurde honom: «Kvi magrast du so, du kongsson, frå dag til annan? Fortel meg det?» Amnon svara: «Eg hev huglagt Tamar, syster åt Absalom, bror min!»',
        5: 'Då sagde Jonadab til honom: «Legg deg sjuk på sengi di! Og når far din kjem og ser til deg, so bed honom: «Kjære, lat Tamar, syster mi, koma og laga maten åt meg! Lat henne laga til mat for augo mine, so eg ser på! Og lat meg eta av hennar hand!»»',
        6: 'Amnon lagde seg og lest som han var sjuk. Kongen kom og såg til honom. Og Amnon bad kongen: «Kjære, lat Tamar, syster mi, koma og laga tvo kakor åt meg so eg ser på og fær eta av hennar hand!»',
        7: 'David sende då bod inn i huset til Tamar og bad henne: «Gakk til huset åt Amnon, bror din, og laga noko mat åt honom!»',
        8: 'Tamar gjekk til huset åt Amnon, bror sin, der han låg til sengs. Ho tok deig og knoda, og laga kakorne so han såg på, og steikte deim.',
        9: 'So tok ho panna og hadde deim or for honom; men han vilde ikkje eta. So sagde Amnon: «Gakk ut alle mann!» Og dei so gjorde.',
        10: 'So segjer han med Tamar: «Kom med maten her inn i kammerset, so eg fær eta av handi di!» Og Tamar tok kakorne ho hadde laga, og gjekk inn i kammerset til Amnon, bror sin.',
        11: 'Men då ho bar deim fram åt honom, so han skulde eta, greip han fat i henne og sagde: «Kom og ligg med meg, syster mi!»',
        12: 'Ho svara: «Nei, bror min! Du må ikkje skjemma meg! Sovore må ikkje henda i Israel! Gjer ikkje so stygg ei gjerning!',
        13: 'Kvar skulde eg gjera av meg med skammi? Og du sjølv vilde seinare heita eit styggeting i Israel. Tala fyrst med kongen! Han vil ikkje negta deg å få meg.»',
        14: 'Men han vilde ikkje lyda henne. Han valdtok henne, skjemde henne, låg med henne.',
        15: 'Etterpå fekk Amnon brått ein øgjeleg illvilje til henne. Illviljen han åtte mot henne no, var endå meir ofseleg enn elsken han hadde havt til henne fyrr. «Ris upp og gakk med deg!» sagde Amnon til henne.',
        16: 'Ho sagde til honom: «Ikkje auka skuldi med å gjera so stor ei ugjerning som å jaga meg! det vil vera endå verre enn det andre du hev gjort med meg.» Men han vilde ikkje høyra på henne,',
        17: 'men ropa på drengen, som tente hjå honom: «Få henne der burt frå meg, ut på gata!» ropa han, «og læs døri etter henne!»',
        18: 'Ho gjekk i sid ermekjole; i sovorne kappor var kongsdøtterne klædde med dei var unge gjentor. Tenaren førde henne ut på gata og læste døri etter henne.',
        19: 'Då tok Tamar oska og hadde på hovudet, reiv sund ermekjolen ho gjekk i, lagde handi på hovudet og gjekk og øya seg i eino.',
        20: 'Absalom, bror hennar, spurde henne: «Hev Amnon, bror din, vore hjå deg? Teg deg no, syster! Han er bror din. Bry deg ikkje um dette!» Tamar heldt seg då heime hjå Absalom, bror sin, einsleg og yvergjevi.',
        21: 'Då kong David spurde alt dette, loga harmen upp i honom.',
        22: 'Absalom sagde ingen ting med Amnon anten godt eller vondt. Men Absalom hata Amnon, for di han hadde skjemt Tamar, syster hans.',
        23: 'Tvo år etter hadde Absalom saueklypping i Ba’al-Hasor attmed Efraim; og Absalom bad alle kongssønerne til gjester.',
        24: 'Absalom gjekk då inn til kongen og sagde: «Tenaren din held saueklypping. Eg bed at kongen og tenarane hans vil vera med.»',
        25: 'Kongen svara Absalom: «Nei, guten min! Me må ikkje vera med alle; det vert for mykje bry for deg.» Endå han naudbad honom, vilde han ikkje, men bad farvel med honom.',
        26: 'Då sagde Absalom: «So lat då i alle fall bror Amnon vera med!» Kongen spurde: «Kvifor nett han?»',
        27: 'Men då Absalom naudbad honom, let han Amnon og alle kongssønerne vera med.',
        28: 'Absalom baud drengjerne: «Sjå etter når Amnon vert lystig av vinen, og eg segjer: «Hogg til Amnon!» So drep honom hugheilt! eg tek ansvaret. Ver hugsterke, og vis de er dugande karar!»',
        29: 'Absaloms-drengjerne gjorde med Amnon som Absalom hadde bode. Då spratt dei upp alle kongssønerne, steig på muldyri sine og rømde.',
        30: 'Med dei endå var på vegen, fekk David høyra ei tiend um at Absalom hadde drepe alle kongssønerne, so ikkje ein einaste var att av deim.',
        31: 'Då reiste kongen seg og reiv sund klædi sine og lagde seg på golvet. Og alle tenarane som stod der, reiv og sund klædi sine.',
        32: 'Men Jonadab, son åt Simea, bror åt David, tok til ords og sagde: «Herre, du må ikkje tru at dei hev drepe alle dei unge kongssønerne. Det er berre Amnon som er dåen. Eg hev lese ulukka på Absaloms munn alt frå den dagen då Amnon skjemde ut Tamar, syster hans.',
        33: 'Herre konge! no må du ikkje gjera deg so ilt av det, at du trur alle kongssønerne er daude. Nei, det er berre Amnon som er daud.»',
        34: 'Men Absalom flydde. Då vaktmannen såg ut, fekk han sjå mykje folk kom vegen ned fjellet attanfor.',
        35: 'Då sagde Jonadab til kongen: «Der kjem kongssønerne! Det er som eg sagde.»',
        36: 'Nett då han hadde tala ut, kom kongssønerne, og dei sette i og gret. Ogso kongen og alle tenarane storgret og stridgret.',
        37: 'Men Absalom flydde og for til Talmai Ammihudsson, kongen i Gesur. Og han syrgde yver son sin heile tidi.',
        38: 'Absalom flydde og for til Gesur, og heldt seg der i tri år.',
        39: 'Men kong David let vera å draga ut mot Absalom; han hadde lote trøysta seg i sorgi yver at Amnon var dåen.',
    },
    14: {
        1: 'Joab Serujason skyna at kongen endå var glad i Absalom.',
        2: 'Han sende då bod til Tekoa og henta ei sløg kona derifrå og baud henne: «Te deg som du hev sorg! Klæd deg i syrgjebunad! Smyr deg ikkje med olje! Te deg som ei kvinna som hev syrgt på ein avliden i lang tid!',
        3: 'Gakk so inn til kongen og tala til honom desse ordi!» - Joab lagde henne ordi i munnen.',
        4: 'Tekoa-kona tala til kongen, fall å gruve ned på jordi og bøygde seg, og ropa: «Hjelp, konge!»',
        5: 'Kongen spurde: «Kva er i vegen med deg?» Ho svara: «Å, eg er ei syrgjande enkja; mannen min er dåen.',
        6: 'Tenestkvinna di hadde tvo søner. Dei kom i trætta med kvarandre ute på marki; og det var ingen til å skilja deim; den eine gav då bror sin banehogg.',
        7: 'No ris heile ætti upp mot tenestkvinna di og krev: «Hit med brormordaren! Me vil drepa honom til hemn for han myrde bror sin! So fær me rudt ervingen or vegen med same!» Og soleis vil dei sløkkja den siste voni eg hev att i livet, og meinka mannen min både ettermæle og avkjøme her på jordi.»',
        8: 'Kongen sagde til kona: «Far heim! eg skal greida saki for deg.»',
        9: 'Men Tekoa-kona svara kongen: «Herre konge! På meg og på farsætti mi kvile all skuldi! Men kongen og kongsstolen lyt vera utan skuld!»',
        10: 'Då sagde kongen: «Segjer nokon eitkvart med deg, so kom hit med honom! han skal ikkje gjera deg mein ein gong til.»',
        11: 'Ho sagde: «Kom i hug Herren, din Gud, konge, so blodhemnaren ikkje skal auka ulukka og rydja son min or vegen.» Då sagde han: «So sant Herren liver, ikkje eit hår skal verta skadt på hovudet åt son din!»',
        12: 'Då tok kona til ords: «Lat tenestkvinna di endå få lov å segja eit ord med deg, herre konge!» Han svara: «Seg det!»',
        13: '«Kvifor hev du tenkt so vondt mot Guds folk?» sagde kona; «når kongen talar so, då er det som um han hev dømt seg sjølv, med di kongen let ikkje sin burtstøytte son koma heim att.',
        14: 'Vist lyt me alle døy. Men likjest på vatnet som vert utrent på marki, og som ein ikkje kann samla upp att. Men Gud let ingen døy, utan han tenkjer ut alt som tenkjast kann til å berga den burtstøytte so han ikkje vert burtstøytt frå honom.',
        15: 'Eg er komi til å tala desse ordi med deg no, herre konge, av di skyldfolket mitt hev skræmt meg. Tenestkvinna di kom i hug: «Eg vil tala med kongen; kann henda kongen vil gjera det eg bed um.',
        16: 'Ja, kongen vil lyda på tenestkvinna si, og berga meg frå den som vil rydja or vegen både meg og son min or Guds eige folk.»',
        17: 'Og tenestkvinna di tenkte: «Eit ord frå deg, herre konge, vil gjera meg sutlaus! For du, herre konge, er som Guds engel, med di du høyrer alt både godt og vondt.» So vere Herren, din Gud, med deg!»',
        18: 'Då tok kongen åt ords og sagde til kona: «Svara meg ope og ærleg på det som eg no spør deg!» Ho svara: «Seg det, herre konge!»',
        19: 'Kongen spurde: «Hev ikkje Joab si finger med i dette spelet?» Kona svara: «So sant som du liver, herre konge, når du talar, herre konge, kann ingen koma undan anten til høgre eller vinstre. Jau, det er Joab, tenaren din, som hev lagt dette på meg, og lagt tenestkvinna di i munnen alt det eg hev sagt.',
        20: 'Joab, tenaren din, hev gjort det, av di han vilde få saki til å sjå onnorleis ut. Men du, herre, er vis som Guds engel, so du veit alt som hender på jordi.»',
        21: 'Kongen sagde då til Joab: «Godt og vel! eg skal so gjera. Far av og før heim den unge mannen, Absalom!»',
        22: 'Då fall Joab å gruve, bøygde seg til jordi og velsigna kongen. Joab sagde: «I dag skynar tenaren din at du, herre konge, eig godvilje for meg, sidan du, konge, gjer det eg bed um.»',
        23: 'Joab reis upp og drog til Gesur, og førde Absalom til Jerusalem.',
        24: 'Kongen gav det bodet: «Han lyt ganga heim til seg sjølv. For mine augo skal han ikkje koma.» So gjekk Absalom heim til seg sjølv, og kom ikkje kongen for augo.',
        25: 'I heile Israel beid ikkje maken til Absalom so væn, og ingen so namngjeten; det beid ikkje lyte på honom frå kvervel til iljar.',
        26: 'Når han klypte håret på hovudet sitt - det gjorde han på slutten av kvart år; for det var so tungt at han laut klyppa det - då vog dei håret hans, og fann at det vog tvo hundrad lodd etter kongens vegt.',
        27: 'Absalom hadde tri søner og ei dotter; ho heitte Tamar og var fager å sjå til.',
        28: 'Då Absalom hadde halde seg tvo år i Jerusalem og ikkje kome kongen for augo,',
        29: 'sende han bod etter Joab, var meint å senda honom til kongen. Men han vilde ikkje koma. Andre gongen sende han bod; han vilde ikkje koma.',
        30: 'Då sagde han med tenarane sine: «De veit at Joab hev ein åkerteig ved sida av min; og der hev han bygg. Far dit og kveik eld på!» So kveikte drengjerne åt Absalom eld på åkerteigen.',
        31: 'Joab for upp og gjekk heim til Absalom: «Kvi hev drengjerne dine kveikt eld på åkerteigen min?» spurde han.',
        32: '«Eg sende då bod etter deg,» svara Absalom, «og bad deg koma hit, so eg kunde senda deg til kongen med desse ordi: «Kvifor fekk eg koma heim frå Gesur? det vøre betre for meg um eg hadde halde meg der framleides.» No vil eg fram for kongen. Er eg saka i nokor illgjerning, so fær han drepa meg.»',
        33: 'Då gjekk Joab til kongen og melde honom det. Kongen kalla då til seg Absalom; og han kom inn til kongen, kasta seg å gruve for honom og bøygde seg til jordi framfor kongen. Og kongen kysste Absalom.',
    },
    15: {
        1: 'Ei stund etterpå fekk Absalom seg vogn og hestar og femti mann som sprang fyre honom.',
        2: 'Tidleg um morgonen pla Absalom standa attmed vegen til porten. So tidt nokon var på veg til kongen med eikor saki han vilde hava dom i, ropa Absalom honom til seg og spurde: «Kva by er du frå?» Når han svara: «Frå den og den ætti i Israel er tenaren din,»',
        3: 'so svara Absalom: «Du veit saka di er både god og rett, men hjå kongen finn du inkje ope øyra.»',
        4: 'Og han lagde til: «Gjev dei gjera meg til domar i landet! Då skulde kvar ein koma til meg med saker og søksmål. Og eg skulde gjeva honom rett.»',
        5: 'Gjekk einkvan fram og vilde bøygja seg for honom, retta han ut handi og tok um honom og kysste honom.',
        6: 'Soleis gjorde Absalom med alle i Israel som kom med saker kongen skulde døma i. Og Absalom dåra hugen hjå Israels-sønerne.',
        7: 'Fire år var lidne, då Absalom ein dag bad kongen: «Lat meg draga til Hebron og halda ein lovnad eg hev gjort åt Herren!',
        8: 'Då tenaren din budde i Gesur i Syria, gjorde eg den lovnaden: «Let Herren meg verkeleg koma heim att til Jerusalem, so vil eg halda ei gudstenesta åt Herren.»»',
        9: 'Kongen svara: «Far i fred!» Han reis upp og drog til Hebron.',
        10: 'Absalom sende so njosnarar til alle ætterne i Israels med dei ordi: «Når de høyrer luren ljoda, då kann det fortelja at Absalom hev vorte konge i Hebron.»',
        11: 'Med Absalom fylgde tvo hundrad mann frå Jerusalem, som var innbodne og fylgde med i god tru; dei visste ingen ting.',
        12: 'Medan Absalom ofra slagtofferi, sende han bod og henta dessutan Ahitofel, rådsmannen åt David, frå Gilo, heimbyen hans. Samansverjingi auka i styrke. Folket heldt på og gjekk yver til Absalom i store mengder.',
        13: 'Ein bodberar kom til David og melde: «Israels-mennerne hev vendt hugen sin til Absalom.»',
        14: 'Då baud David alle tenarane sine, dei som var hjå honom i Jerusalem: «Av stad! Det finst ingi onnor råd for oss til å berga oss undan Absalom. Skunda dykk av stad, so han ikkje kjem brått på oss og fører ulukka yver oss og drep byfolket!»',
        15: 'Kongstenarane svara: «Tenarene dine er budde til alt det du vil, herre konge!»',
        16: 'Då drog kongen ut; og alle husfolki hans fylgde. Ti av fylgjekonorne let kongen att til å vakta huset.',
        17: 'Då kongen drog av stad, fylgde alt byfolket. Dei stogga ved Bet-Hammerhak.',
        18: 'Alle tenarane gjekk framum honom, like eins heile livvakti. Og alle Gats-folki, seks hundrad mann som hadde fylgt honom frå Gat, gjekk framum kongen.',
        19: 'Kongen sagde med Gats-mannen Ittai: «Kvifor gjeng du og med oss? Far attende, og ver hjå honom som no er konge! Du er då berre utlending, ja ein heimlaus utvandrar.',
        20: 'Du kom i går! Skulde eg i dag lata deg reika ikring med oss på ferdi vår, no eg ikkje sjølv veit leidi? Far attende, og tak brørne dine med deg! Gjev miskunn og truskap må timast dykk!»',
        21: 'Men Ittai svara kongen: «So sant Herren liver, og so sant du liver, herre konge: den staden du er, herre konge, der vil tenaren din ogso vera, anten det ber til liv eller daude!»',
        22: 'David sagde då til Ittai: «Ja ja, ver so med!» Gats-mannen Ittai drog då med, fylgd av alle sine menner og heile barneflokken som han hadde med seg.',
        23: 'Heile landet storgret då alt folket drog fram. Og då kongen gjekk yver Kidronsbekken, fylgde alt folket etter og tok vegen åt øydemarki.',
        24: 'Sjå Sadok og alle levitarne var og med honom. Dei bar Guds sambandskista med seg. Dei sette Guds kista ned - då kom Abjatar og upp - til dess alt folket hadde rokke fram frå byen.',
        25: 'Kongen sagde då til Sadok: «Før Guds kista attende til byen! Syner Herren meg miskunn, so let han meg koma heim att, so eg fær sjå att honom og bustaden hans.',
        26: 'Men segjer han: «Eg hev ikkje godvilje for deg,» då er eg budd: han gjere med meg som han tykkjer!»',
        27: 'Og kongen sagde med presten Sadok: «Du sjåar. Far heim att i fred! Og båe sønerne dykkar, Ahima’as, son din, og Jonatan Abjatarsson, må fylgja med dykk.',
        28: 'Sjå, eg vil drygja attmed ferjestaderne i øydemarki til dess eg fær bod frå dykk med meldingar.»',
        29: 'So førde Sadok og Abjatar Guds kista attende til Jerusalem og stana der.',
        30: 'David gjekk gråtande upp Oljefjellet med tilsveipt hovud og berrføtt. Og alt folket som fylgde, hadde og sveipt til hovudi sine og gjekk gråtande dit upp.',
        31: 'Då David fekk høyra at Ahitofel var millom deim som hadde samansvore seg med Absalom, bad David: «Herre, gjer Ahitofels råd til skammar!»',
        32: 'Då David var komen øvst på fjellet, der dei plar tilbeda Gud, då kom Husai av arkitætti mot honom med sundrivne klæde og mold på hovudet.',
        33: 'David sagde til honom: «Gjeng du med meg, vert du til bry for meg.',
        34: 'Men gjeng du attende til byen og segjer med Absalom: «Din tenar vil eg vera, konge! far din’s tenar var eg fyrr; no er eg din tenar!» - so kann du hjelpa meg å skjepla Ahitofels råd.',
        35: 'Du veit du hev prestarne Sadok og Abjatar ogso der. Alt du frettar frå kongshuset, må du melda åt prestarne Sadok og Abjatar.',
        36: 'Dei hev ogso båe sønerne sine heime: Sadok hev Ahima’as, og Abjatar hev Jonatan. Med deim kann du senda meg bod um alt du fretter.»',
        37: 'So gjekk då Husai, venen åt David, inn i byen, samstundes som Absalom drog inn i Jerusalem.',
    },
    16: {
        1: 'Då David var komen eit stykke på hi sida av fjellet, møtte han Siba, drengen åt Mefiboset, med eit par asen kløvja med tvo hundrad brød, hundrad rosinkakor, hundrad sumarfrukter og ei vinhit.',
        2: 'Kongen spurde Siba: «Kva er det du hev der?» Siba svara: «Asni skal vera til å rida på for kongens husfolk. Brødet og frukterne skal vera mat åt tenarane; og vinen til svaledrykk for dei trøytte mennerne dine i øydemarki.»',
        3: 'Kongen spurde: «Kvar er son åt husbonden din?» Siba svara: «Han er att i Jerusalem. Han tenkte at no vil Israels hus gjeva honom att kongedømet åt far hans.»',
        4: 'Då sagde kongen til Siba: «Alt det Mefiboset eig, skal vera ditt!» Siba svara: «Eg fell ned for deg. Lat meg eiga godviljen din, herre konge!»',
        5: 'Då kong David so kom til Bahurim, kom ut derifrå ein mann av Sauls-ætti, Sime’i Gerason heitte han. Han gjekk og banna',
        6: 'og kasta stein etter David og alle kongstenarane, endå heile heren og det djervaste stridsfolket gjekk på båe sidor av kongen.',
        7: 'Soleis banna Sime’i: «Burt, burt med deg, din blodhund! din niding!',
        8: 'Herren let no alt blodet frå Sauls hus koma att yver deg, du som vart konge i hans stad. Herren gjev no kongedømet til Absalom, son din. Sjå no hev du fenge ulukka etter fortenesta! ein blodhund er du!»',
        9: 'Abisai Serujason spurde kongen: «Kvifor skal den daude hunden der hava lov å banna deg, herre konge? Lat meg fara dit og hogga hovudet av honom!»',
        10: 'Men kongen svara: «Kva hev eg med dykk å gjera, Seruja-søner? Bannar han, og er det Herren som hev bode honom å banna David, kven vågar då spyrja: «Kvi gjer du so?»»',
        11: 'Og David sagde med Abisai og med alle folki sine: «De veit son min vil taka livet av meg - han som er runnen av mi rot. Kor mykje større grunn hev då denne benjaminiten! Lat honom berre banna, når Herren hev bode honom å banna.',
        12: 'Kann henda Herren ser til mi naud og gjev meg lukka til vederlag for den forbanningi som kjem yver meg i dag.»',
        13: 'David og mennerne hans gjekk so burtetter vegen, medan Sime’i fylgde honom jamsides uppi lidi, og banna i eino og kasta stein og molda honom ut med mold.',
        14: 'Kongen kom med alle folki sine til Ajefim og kvilde seg der.',
        15: 'Absalom var komen til Jerusalem med alle sine folk av Israels-mennerne. Han hadde ogso Ahitofel med seg.',
        16: 'Då arkiten Husai, venen åt David, kom til Absalom, ropa han imot honom: «Live kongen, live kongen!»',
        17: 'Absalom spurde Husai: «Er det soleis du syner godvilje mot venen din? Kvifor hev du ikkje fylgt venen din?»',
        18: 'Husai svara Absalom: «Nei, den som Herren og folket og alle Israels-mennerne hev valt, til honom vil eg høyra, hjå honom vil eg vera.',
        19: 'Dessutan: kven er det eg tenar? Er det ikkje son hans? Like eins som eg hev tent hjå far din, so vil eg no vera hjå deg.»',
        20: 'Absalom bad Ahitofel: «Kom med ei råd, kva skal me gjera no.»',
        21: 'Ahitofel svara: «Ligg med fylgjekonorne åt far din, som han let att til å vakta kongsgarden! Då fær heile Israel høyra gjete at du hev gjort far din hatig på deg. Og so fær dei nytt mod alle som hev fylgt deg.»',
        22: 'So slo dei upp tjeld åt Absalom uppå taket. Og Absalom låg med fylgjekonorne åt far sin, so heile Israel såg på.',
        23: 'I dei dagarne galdt ei råd som Ahitofel gav, like mykje som svar frå Gud. So mykje galdt alle Ahitofels råder både hjå David og hjå Absalom.',
    },
    17: {
        1: 'Ahitofel sagde med Absalom: «Lat meg velja ut tolv tusund mann, so vil eg leggja i veg og forfylgja David alt i natt!',
        2: 'So kjem eg brått yver honom og skræmer honom medan han er trøytt og veik. Då vil alle folki hans taka til rømings. So drep eg kongen medan han er åleine.',
        3: 'So skal eg føra alt folket attende til deg; for um det gjeng so med den mannen du søkjer, er det som alle kjem attende; heile folket vil halda fred.»',
        4: 'Absalom og alle dei øvste i Israel lika godt den rådi.',
        5: 'Like vel sagde Absalom: «Ropa ogso arkiten Husai inn! so fær me ogso høyra kva han råder til.»',
        6: 'Då Husai kom inn til Absalom, sagde Absalom til honom: «So og so hev Ahitofel sagt. Skal me fylgja hans råd? I anna fall, kva meiner du?»',
        7: 'Husai svara Absalom: «Den rådi Ahitofel hev gjeve denne gongen, er ikkje god.',
        8: 'Du kjenner far din og folki hans,» sagde Husai, «du veit dei er fullgode stridsfolk. Og hug-rame er dei no som ei binna dei hev teke ungarne frå ute i marki. Far din er krigsmann, veit du: han let ikkje folki leggja seg til kvile um natti.',
        9: 'No hev han visseleg løynt seg i einkvan helleren eller einkvar annan staden. Skulde då sume av våre folk falla i fyrstningi, so vil det koma ut at det hev vore stort mannefall millom folki som fylgde Absalom.',
        10: 'Då vil jamvel den djervaste heiltupp missa modet, um han så hadde mod som ei løva. For heile Israel veit at far din er ei kjempa, og at fylgjesveinarne hans er djerve karar.',
        11: 'Difor er det mi råd, at du stemner saman til deg heile Israel frå Dan til Be’erseba, so tallrikt som sanden attmed havet. Og sjølv lyt du draga med i striden.',
        12: 'Når me so finn honom einkvan staden, kvar helst det no er, so fell me yver honom som doggi fell på marki. Då skal det ikkje verta ein einaste att av honom og alle fylgjesveinarne hans.',
        13: 'Ja, um han so søkjer inn i ei borg, so vil heile Israel leggja reip ikring henne og draga henne ned i dalen, til dess det bid ikkje minste steinen att i henne.»',
        14: 'Då sagde Absalom og alle Israels-mennerne: «Rådi åt arkiten Husai er betre enn Ahitofels råd.» For Herren laga det so at den gode rådi hans Ahitofel vart um inkjes. For Herren vilde føra ulukke yver Absalom.',
        15: 'Husai melde til prestarne Sadok og Abjatar: «Den og den rådi gav Ahitofel åt Absalom og dei øvste i Israel. Men den og den rådi gav eg.',
        16: 'Skunda dykk og send bod til David med det ordet: «Natta ikkje yver attmed ferjestaderne i øydemarki i natt, men gakk yver Jordan! Elles kann kongen og alle folki hans verta tynte.»»',
        17: 'Jonatan og Ahima’as heldt seg attmed En-Rogel. Dit kom jamt ei tenestgjenta med melding til deim; og so bar dei meldingi til David. Dei våga ikkje visa seg i byen.',
        18: 'Men ein unggut gådde deim og melde det til Absalom. Då skunda dei seg burt båe, og kom heim til ein mann i Bahurim. Han hadde ein brunn på garden sin. I den steig dei ned.',
        19: 'So tok kona hans og breidde eit tæpe yver brunn-opet, og strådde gryn uppå, so ingen gådde noko.',
        20: 'Då tenarane åt Absalom kom inn i huset til kona og spurde etter Ahima’as og Jonatan, svara ho: «Dei gjekk yver den vesle bekken der.» Dei leita, men fann inkje, og snudde so heim att til Jerusalem.',
        21: 'Då dei hadde fare sin veg, steig dei hine upp or brunnen, og gjekk med meldingi til kong David. Dei sagde til David: «Skunda deg, far yver vatnet! den og den rådi hev Ahitofel gjeve um dykk.»',
        22: 'David braut upp med alle fylgjesveinarne sine; og dei gjekk yver Jordan. Um morgonen då dagen rann, vanta det ikkje ein einaste. Alle var komne yver Jordan.',
        23: 'Då Ahitofel såg at dei ikkje fylgde rådi hans, sala han asnet sitt, steig uppå og reid heim til sin by. Og då han hadde skila for seg, hengde han seg. Det var hans bane. Han vart gravlagd i gravi åt far sin.',
        24: 'David var komen til Mahanajim då Absalom med alle Israels-mennerne gjekk yver Jordan.',
        25: 'Absalom hadde sett Amasa til øvste herhovding i staden for Joab. Amasa var son åt ein jizre’elit ved namn Jitra, som hadde halde seg med Abigal, dotter til Nahas, syster til Seruja, mor åt Joab.',
        26: 'Israel og Absalom lægra seg i Gileadlandet.',
        27: 'Då David kom til Mahanajim, hadde Sobi Nahasson frå Rabba i Ammonitarlandet og Makir Ammielsson frå Lo-Debar, og Barzillai, ein Gileads-mann frå Rogelim,',
        28: 'ført dit sengjer, skåler og kruskjerald. Og kveite, bygg, mjøl, steikte aks, baunor, linsor,',
        29: 'honning, tjukkmjølk, sauer og mjølk-ost hadde dei med seg til mat åt David og folket hans. For dei tenkte: «Folki hev vorte svoltne, trøytte og tyrste i øydemarki.»',
    },
    18: {
        1: 'David mynstra folket sitt og sette førarar og underførar yver deim.',
        2: 'So sende David ut folket; den eine tridjeparten under Joab, den andre tridjeparten under Abisai Serujason, bror åt Joab, og den tridje under Ittai frå Gat. Og kongen sagde til folket: «Eg er fast meint på å draga ut sjølv med dykk.»',
        3: 'Men dei svara: «Du fær ikkje draga ut. Um me lyt røma, bryr ingen seg um oss. Um helvti av oss vert drepne, bryr ingen seg um oss. Men du er no jamgod med titusund av oss. Difor er det likare at du er budd på å koma oss til hjelp frå byen.»',
        4: 'Kongen sagde: «Det de meiner er best, det vil eg gjera.» So tok kongen post attmed porten. Og heile heren drog ut i hundrad og i tusund.',
        5: 'Kongen baud Joab, Abisai og Ittai: «Far no varsamt med den unge mannen, med Absalom!» Heile heren høyrde kva kongen baud herhovdingarne um Absalom.',
        6: 'So drog heren ut i opi marki mot Israel. Og det kom til slag i Efraimsskogen.',
        7: 'Der vart Israels-heren slegen av Davids herfolk. Og vart stort mannefall millom deim den dagen: tjuge tusund mann.',
        8: 'Slaget spreidde seg utyver heile den kanten av landet. Og skogen øydde fleire folk den dagen enn sverdet.',
        9: 'Det bar so til at Absalom råka på nokre av folki åt David. Han reid på eit muldyret. Og då muldyret kom inn under dei tette greinerne av ei stor eik, vart hovudet hans klemt fast millom greinerne. Og han vart hangande millom himmel og jord. For muldyret han reid på, sprang sin veg.',
        10: 'Ein mann som såg det, melde det til Joab: «Eg fekk sjå Absalom hangande i ei eik der burte.»',
        11: 'Joab spurde bodberaren: «Når du såg det, kvifor slo du honom ikkje til marki med same? So skulde eg gjerne ha gjeve deg ti sylvdalar og eit belte for det.»',
        12: 'Mannen svara: «Um eg so skulde fenge ti tusund sylvdalar upp i neven, so ikkje eg leggja hand på kongssonen. Me høyrde då med eigne øyro kor kongen baud deg og Abisai og Ittai: «Tak vare på den unge mannen, på Absalom, for meg.»',
        13: 'Og hadde eg gjort svik mot hans liv - for ingen ting vert løynd for kongen - so vilde du halde deg utanfor.»',
        14: '«Eg vil ikkje hefta tidi lenger meg deg,» sagde Joab, treiv tri spjot i handi, og deim rende han i bringa på Absalom, som endå hekk livande millom greinerne på eiki.',
        15: 'So kom ti sveinar til, Joabs våpnsveinar, og gav Absalom banehogg.',
        16: 'Joab bles i luren. Og herfolket heldt upp med å forfylgja Israel, då Joab baud deim stogga.',
        17: 'Dei tok og kasta Absalom i ei stor grop i skogen, og hauga i hop ei veldug steinrøys yver honom. Heile Israel tok til rømings kvar til seg.',
        18: 'Absalom sjølv hadde i livande live teke og reist upp til minne for seg den merkesteinen som stend i Kongsdalen; med di han sagde: «Eg hev ingen son til å halda uppe namnet mitt!» Han kalla merkesteinen etter sitt namn; og han heiter «Absaloms minne» endå den dag i dag.',
        19: 'Ahima’as Sadoksson sagde: «Lat meg skunda meg og melda kongen fagnadtiendi, at Herren hev hjelpt honom til retten sin mot uvenerne sine!»',
        20: '«Nei,» sagde Joab, «det vert inkje fagnadbod det du hev å bera i dag. Ein annan dag kann du koma med fagnadtiend. Men i dag vert det ingen fagnadtiend; for det er son åt kongen som er avliden.»',
        21: 'So baud Joab ein ætiop: «Gakk og meld kongen det du hev set!» Ætiopen fall ned for Joab og sprang av stad.',
        22: 'Ahima’as Sadoksson bad Joab andre gongen: «Kome kva kome vil: lat meg springa eg og, etter ætiopen!» Joab svara: «Kvifor vil du det, guten min? Dette er då ikkje nokor fagnadtiend, som du kann venta løn for!»',
        23: 'Han sagde: «Koma kva kome vil: eg spring!» «So spring då!» sagde Joab. Og Ahima’as sprang, og tok vegen yver Jordan-kverven og kom fyre ætiopen.',
        24: 'David sat inni dubbelporten. Og ein vaktmann steig upp på porttaket innmed muren. Då han skoda ut, fekk han sjå ein koma springande åleine.',
        25: 'Vaktmannen ropa og melde det åt kongen. Då sagde kongen. «Er han åleine, so hev han eit fagnadbod å bera fram. Men medan han kom næmare,',
        26: 'fekk vaktmannen sjå ein annan kom springande. Då ropa vaktmannen ned til portvakti: «No ser eg ein til kjem springande åleine.» Kongen sagde: «Han kjem og med fagnadbod.»',
        27: 'Vaktmannen sagde: Etter måten å springa på, tykkjer eg den fyrste må vera Ahima’as Sadoksson.» Kongen sagde: «Han er ein god mann! han kjem visseleg med fagnadtidend.»',
        28: 'Ahima’as ropa til kongen: «Heil og sæl!» So fall han å gruve til jordi framfor kongen og sagde: «Lova vere Herren, din Gud! Han hev gjeve deg dei mennerne som lyfte handi mot deg, herre konge!»',
        29: 'Kongen spurde: «Stend det vel til med den unge mannen, med Absalom?» Ahima’as svara: «Eg såg ei stor mannemuge då Joab sende den andre kongstenaren og meg. Men eg veit ikkje kva det galdt.»',
        30: 'Kongen sagde: «Gakk til sides, og statt der!» Han so gjorde.',
        31: 'Nett då kom ætiopen. Han sagde: «Tak imot fagnadbodet, herre konge, at i dag hev Herren gjeve deg rett mot alle deim som reiste seg mot deg.»',
        32: 'Kongen spurde ætiopen: «Stend det vel til med den unge mannen, med Absalom?» Ætiopen svara: «Gjev det må ganga soleis med uvenerne dine, herre konge, og med alle som reiser seg mot deg og vil gjera deg mein, som det gjekk med den unge mannen!»',
        33: 'Då vart kongen reint ille ved, gjekk upp i taksalen yver porten, og gret. Og alt medan han gjekk, jamra han: «Absalom, son min, Absalom, son min, son min! Gjev eg hadde døytt i staden din! Absalom, son min, son min!»',
    },
    19: {
        1: 'Joab spurde at kongen gret og syrgde yver Absalom.',
        2: 'Sigeren vart soleis umskift til ei stor folkesorg den dagen. For herfolket høyrde gjete den dagen at kongen bar sorg for son sin.',
        3: 'Folket stal seg inn i byen den dagen, soleis som folk plar gjera når dei skjemmest av di dei hev rømt frå slaget.',
        4: 'Kongen hadde sveipt eit plagg kring andlitet sitt, og jamra med høgt mål: «Absalom, son min! Absalom, son min, son min!»',
        5: 'Då gjekk Joab inn i huset til kongen og sagde: «Du hev i dag fenge alle tenarane dine til å raudna av skam, endå dei i dag hev berga ditt liv og berga livet åt sønerne og døtterne dine, åt konorne og fylgjekonorne dine.',
        6: 'Du elskar då deim som hatar deg, og hatar deim som elskar deg. Du hev kunngjort i dag at hovdingarne og tenarane dine er inkjevetta for deg. Eg skynar det no, at det vilde du ha lika godt: um Absalom hadde vore i live, og alle me andre no vore drepne.',
        7: 'Ris upp! gakk ut, og tala venleg med tenarane dine! Det sver eg ved Herren: Gjer du ikkje det, so vil ikkje ein einaste mann natta yver hjå deg i natt. Og det vil verta større ulukka for deg enn alle andre ulukkor som hev kome yver frå din ungdom til no.»',
        8: 'Då reis kongen upp og sette seg i porten. Det vart kunngjort for alt herfolket: «Sjå kongen sit no i porten.» Då kom dei alle fram for kongen. Israel hadde rømt kvar til seg.',
        9: 'Og alt folket i alle Israels ætter tok til å tretta med kvarandre og segja: «Kongen var det som fria oss frå fiendarne våre og berga oss frå filistarane. No hev han lote røma landet for Absalom.',
        10: 'Absalom, som me salva til konge yver oss, han er drepen i krigen. Kvifor drygjer de då med å få kongen attende?»',
        11: 'Alt dette vart bore fram for kongen der han heldt seg. David sende bod til prestarne Sadok og Abjatar og bad deim bera fram dette bodet: «Tala so til dei øvste i Juda: «Kvifor vil det vera dei siste til å henta kongen heim att til kongsgarden?»',
        12: 'De er brørne mine! me er då same folket! kvifor vil de då vera dei siste til å henta kongen attende?»',
        13: 'Til Amasa bad han deim segja: «Er ikkje me same folket? Gud late meg bøta no og sidan, um ikkje du skal verta herhovdingen min for alle tider i staden hans Joab.»',
        14: 'Han vann soleis Juda-mennerne alle som ein, so dei sende dette bodet til kongen: «Kom heim att, du og alle tenarane dine!»',
        15: 'Då snudde kongen på heimvegen og kom til Jordan. Juda-folket møtte kongen i Gilgal og førde honom yver Jordan.',
        16: 'Og benjaminiten Sime’i Gerason frå Bahurim skunda seg og drog ned med Juda-folket og møtte kong David.',
        17: 'Med honom fylgde tusund mann frå Benjamin. Like eins kom Siba, sveinen åt Sauls-ætti, med femtan søner og tjuge tenarar. Dei kom fram til Jordan fyre kongen.',
        18: 'Dei ferja yver og førde kongslyden yver, og heldt på å ferja so som kongen ynskte. Sime’i Gerason fall å gruve for kongen då han skulde fara yver Jordan.',
        19: '«Herre!» sagde han, «du må ikkje rekna på illgjerningi mi, og ikkje koma i hug kor ille tenaren din gjorde den dagen du, herre konge, drog ut frå Jerusalem! Bry deg ikkje um det, konge!',
        20: 'Tenaren din skyner eg forsynda meg mot deg den gongen. Difor er eg i dag den fyrste av heile Josefs hus som er komen til å møta deg, herre konge!»',
        21: 'Abisai Serujason tok til ords og sagde: «Skulde ikkje Sime’i lata livet for dette, at han banna den som Herren hev salva?»',
        22: 'Men David svara: «Kva hev eg med dykk, Seruja-søner, med di de er motmennerne mine i dag? Ingen mann i Israel skal lata livet i dag. Eg veit: i dag hev eg vorte konge yver Israel.»',
        23: 'So sagde kongen til Sime’i: «Du skal ikkje døy!» Og kongen gjorde eid på det.',
        24: 'Mefiboset, soneson åt Saul, hadde og fare ned og møtt kongen. Han hadde ikkje vølt føterne sine, ikkje greidt skjegget sitt, og heller ikkje vaska klædi sine frå den dagen kongen drog burt, heilt til den dagen han kom att med heilo.',
        25: 'Då no kom til Jerusalem og møtte kongen, spurde kongen honom: «Kvifor fylgde du ikkje med meg, Mefiboset?»',
        26: 'Han svara: «Herre konge, tenaren min sveik meg. Eg sagde: «Eg vil sala asnet mitt, stiga uppå og rida med kongen; du veit eg er lam.»',
        27: 'Men han hev i staden loge på meg for deg, herre konge. Like vel: du, herre konge, er som Guds engel; gjer det du tykkjer best!',
        28: 'Heile farshuset mitt fortente ikkje anna enn daudedom av deg, herre konge! endå sette du meg millom deim som fekk eta ved ditt bord. Kva hev eg då rett å krevja meir? Og kva kann eg meir beda kongen um?»',
        29: 'Kongen svara: «Du tarv ikkje tala meir um det! Eg segjer: Du og Siba skal hava kvar sin lut av jordeigedomen.»',
        30: 'Mefiboset svara kongen: «Han må gjerne eiga alt i hop, sidan du, herre konge, no hev kome att til kongsgarden med heilo.»',
        31: 'Barzillai frå Gilead hadde og fare ned frå Rogelim, og drog so med kongen til Jordan og fylgde honom yver Jordan.',
        32: 'Barzillai var då ovleg gamall, åtteti år. Han hadde sytt for kongen medan han heldt til i Mahanajim; for han var ein rik mann.',
        33: 'Kongen baud no Barzillai: «Du skal fylgja meg; so vil eg syta for deg hjå meg i Jerusalem.»',
        34: 'Men Barzillai svara: «Kor lang tid hev eg att å liva, so eg skulde fylgja kongen upp til Jerusalem?',
        35: 'Eg er no åtteti år, eg. Kann eg då skilja millom godt og låkt? Eller kann eg smaka kva eg et eller drikk? Eller kann eg njota å lyda på songarar og songmøyar? Kvifor skulde eg då meir vera til bry for deg, herre konge?',
        36: 'Berre eit stykke på veg vilde tenaren din fara med kongen yver Jordan. Kvifor skulde kongen gjeva meg vederlag soleis?',
        37: 'Lat tenaren din fara heim att og døy i heimbyen min, der som far og mor ligg gravlagde! Men her er Kimham, tenaren din! Lat honom fylgja med deg, herre konge, og gjer for honom det du tykkjer!»',
        38: 'Kongen svara: «So skal Kimham fylgja med meg. Og eg vil gjera mot honom det du ynskjer. Og alt du bed meg um, skal eg gjera.»',
        39: 'So gjekk alt folket yver Jordan; og kongen sjølv gjekk yver. Kongen kysste Barzillai og tok farvel med honom. Og so vende han heim att.',
        40: 'Kongen drog til Gilgal. Kimham fylgde med, og alle Juda-mennerne. Saman med helvti av Israels-mennerne førde dei kongen dit yver.',
        41: 'Då kom alle Israels-mennerne til kongen og sagde: «Kvifor hev brørne våre, Juda-mennerne, stole seg til å få tak i deg og føra kongen og lyden hans og alle Davids-tenarane yver Jordan?»',
        42: 'Juda-mennerne svara Israels-mennerne: «Kongen stend då næmare oss. Kvifor er de harme for det? Hev me livt på kongen, eller fenge nokor gåva?»',
        43: 'Israels-mennerne svara Juda-mennerne: «Ti gonger større lut enn de hev me i honom som er konge, soleis ogso i David. Kvifor hev de vanvyrdt oss? Var det ikkje me som fyrst tala um å henta kongen vår heim?» Det svaret Juda-mennerne gav, var endå argare enn det Israels-mennerne hadde gjeve.',
    },
    20: {
        1: 'No var det der ei uvyrda ved namn Seba Bikrison, ein benjaminit. Han bles i luren og ropa: «Me hev ingen lut i David og ingen arvlut i Isaisonen. Heim att kvar til seg, Israels menner!»',
        2: 'Alle Israels-mennerne gjekk då frå David og fylgde Seba Bikrison. Men Juda-mennerne heldt fast ved kongen sin, og fylgde honom frå Jordan heilt til Jerusalem.',
        3: 'So kom då David til kongsgarden sin i Jerusalem. Kongen tok då dei ti fylgjekonorne som han hadde late etter seg til å vakta kongsgarden og sette deim under vakt i eit hus for seg sjølve. Han gav deim upphelde; men han heldt seg ikkje med deim. Der budde dei no innestengde til sin døyande dag og livde som enkjor alle sine dagar.',
        4: 'Kongen baud Amasa: «Bjod ut Juda-herfolket åt meg og møt fram med deim innan tri dagar!»',
        5: 'Amasa gjekk og baud ut Juda. Men han drygde utyver den fresten han hadde fenge.',
        6: 'Då sagde David til Abisai: «No kjem Seba Bikrison til å gjera oss meir ilt enn Absalom. Tak du tenarane åt herren din! Set etter honom fyrr han fær hertaka nokor borg og gjera oss for mykje sut!»',
        7: 'Joabs-mennerne drog då av stad etter honom med livvakti og alt stridsfolket. Dei drog ut frå Jerusalem og sette etter Seba Bikrison.',
        8: 'Då dei hadde nått til den store steinen ved Gibeon, møtte dei Amasa med sine hermenner. Joab var klædd i våpnkjole som han var van, med belte um livet og sverd i slira. Då han gjekk fram, datt sverdet ut.',
        9: 'Joab spurde Amasa: «Kor stend det til med deg, bror?» og tok med høgre handi Amasa i skjegget og vilde kyssa honom.',
        10: 'Amasa vara seg ikkje for sverdet som Joab hadde i hi handi. Dermed gav han honom ein støyt i livet, so innvolarne rann ut på marki. Og han døydde på flekken, berre av det. Joab og Abisai, bror hans, heldt fram og forfylgde Seba Bikrison.',
        11: 'Ein av tenarane åt Joab stod der attmed og ropa: «Alle som likar Joab og held med David, fylgje etter Joab!»',
        12: 'Men då mannen såg at alle stogga attmed Amasa, der som han låg midt i vegen kring-velt i sitt eige blod, skuva han liket undan og kasta ei kappa yver; for han såg kor alle stogga når dei kom dit.',
        13: 'Og då liket var teke or vegen, drog alle framum og fylgde Joab og elte Seba Bikrison.',
        14: 'Han hadde i millomtidi fare igjenom alle ætterne i Israel til Abel og Bet-Ma’aka, og kasta seg inn i byen. Og folki hans stemnde i hop og fylgde honom dit inn.',
        15: 'Dei hine kom og kringsette honom der i Abel Bet-Ma’aka og kasta upp ein voll mot byen innimot ytremuren. Alt folket åt Joab stræva med å få muren til å falla, og riva honom ned.',
        16: 'Då ropa ei klok kona frå byen: «Høyr her! Seg Joab han kjem hit, so eg fær tala med honom!»',
        17: 'Då han kom fram til kona, spurde ho: «Er du Joab?» Han svara ja. Ho sagde: «Høyr det tenestkvinna di segjer!» Han svara: «Ja vel.»',
        18: 'Då sagde ho: «Fyrr i tidi pla dei segja: «I Abel skal ein spyrja etter råd;» so kunde ein gjera det ein etla seg til.',
        19: 'Eg er den fredsamaste og trugnaste i heile Israel. Du freistar øyda ein by som er ei mor i Israel! Kvifor vil du øydeleggja Herrens eige folk?»',
        20: 'Joab svara: «Aldri i verdi vil eg øydeleggja og tyna.',
        21: 'Det hev seg ikkje so. Men ein mann frå Efraims fjellbygd - Seba Bikrison heiter han - hev reist seg mot kong David. Gjev honom yver til oss, so dreg eg burt frå byen.» Kona svara Joab: «Hovudet hans skal verta utkasta til deg yver muren.»',
        22: 'Kona kom då til byfolket med si kloke råd. Dei hogg hovudet av Seba Bikrison og kasta det ut til Joab. Då bles han i luren, at herfolket skulde draga burt. Og dei for kvar til seg. Joab snudde heim att til kongen i Jerusalem.',
        23: 'Joab var no øvste herhovding yver heile krigsheren i Israel. Og Benaja Jojadason var hovding yver livvakti.',
        24: 'Adoram hadde uppsyn med pliktarbeidet for kongen. Josafat Ahiludsson var kanslar.',
        25: 'Seja var riksskrivar. Sadok og Abjatar var prestar.',
        26: 'Dessutan var Ira av Ja’irs-ætti prest hjå David.',
    },
    21: {
        1: 'I Davids tid kom tri store uår etter kvarandre. Då gjorde David spursmål til Herren um det. Herren svara: «På Saul og hans hus kvilar blodskuld, av di han drap gibeonitarne.»',
        2: 'Kongen kalla då til seg Gibeon-mennerne og tala med deim. Gibeonitarne var ikkje israelitar, men var ei atterleiva av amoritarne. Endå Israels-borni hadde gjort eiden sin til deim, hadde Saul vore so ihuga for Israels-borni og for Juda, at han freista tyna deim.',
        3: 'David spurde no gibeonitarne: «Kva kann eg gjera for dykk? Korleis kann eg sona brotet, so de vil velsigna Herrens arvlut?»',
        4: 'Gibeonitarne svara: «Ikkje sylv og gull krev me av Saul og hans hus. Og ikkje hev me lov å drepa nokon mann i Israel.» Han spurde: «Kva ynskjer det då eg skal gjera for dykk?»',
        5: 'Dei svara kongen: «Den mannen som vilde tyna oss og tenktest rydja oss ut, so me ikkje lenger skulde få halda oss nokon stad innanfor Israels landskil,',
        6: 'av hans etterkomarar må det gjeva oss sju mann, og me vil leggja deim på stegl for Herrens augo i Sauls Gibea, han som Herren valde ut.» Kongen sagde: «De skal eg gjera.»',
        7: 'Kongen sparde Mefiboset Jonatansson, soneson åt Saul, for skuld den eiden ved Herren som David og Jonatan Saulsson hadde svore einannan.',
        8: 'Derimot tok kongen dei tvo sønerne Armoni og Mefiboset som Saul hadde fenge med Rispa Ajadotter, og dei fem sønerne som Adriel Barzillaison frå Mehola hadde fenge med Mikal Saulsdotter.',
        9: 'Deim gav han yver til gibeonitarne. Og dei lagde deim på stegl på fjellet for Herrens augo. Dei fekk sin bane alle sju på ein gong. Det var dei fyrste skurddagarne, då byggskurden tok til, at dei let livet.',
        10: 'Rispa Ajadotter tok syrgjebunaden sin og breidde ut uppå fjellet frå skurdonni tok til, og til dess det strøymde regn yver deim frå himmelen. Ho let ikkje fuglarne under himmelen slå ned på deim um dagen, heller ikkje villdyri frå marki um natti.',
        11: 'Då David spurde det Rispa Ajadotter, fylgjekona åt Saul, hadde gjort,',
        12: 'drog David av stad og let henta beini etter Saul og Jonatan, son hans, hjå borgarne i Jabes i Gilead. Dei hadde i løynd teke liki frå torget i Bet-San, der som filistarane hadde hengt deim upp då dei hadde slege Saul på Gilboa.',
        13: 'Då han fekk ført beini etter Saul og Jonatan, son hans, upp derifrå, sanka dei i hop beini etter deim som var lagde på stegl,',
        14: 'og gravlagde deim saman med beini etter Saul og Jonatan, son hans, i Benjaminslandet, i Sela, i gravi åt Kis, far hans. Dei gjorde alt det kongen baud. Og etterpå det vende Gud sin nåde til landet.',
        15: 'Det vart krig millom filistarane og Israel att. David drog ned med tenarane sine; og dei slost med filistarane. Men David trøytna.',
        16: 'Jisbo-Benob, ein ætting av Rafa - han hadde eit spjot som vog tri hundrad lodd kopar, og han hadde spent um seg eit nytt sverd - han tenktest drepa David.',
        17: 'Men Abisai Serujason hjelpte kongen og gav filistaren banehogg. Då svor Davids menner ein eid til honom, og sagde: «Du må aldri meir draga ut med oss i strid. Elles kann Israels lampa slokna.»',
        18: 'So hende det sidan at det stod ein bardage med filistarane ved Gob. Då slo husatiten Sibbekai Saf av Rafa-ætti.',
        19: 'Då det endå ein gong stod eit slag mot filistarane ved Gob, gav Elhanan, son åt Ja’are-Orgim frå Betlehem, Goliat frå Gat banehogg, han som hadde eit spjotskaft so stort som ein vevbom.',
        20: 'Då det vart eit slag att ved Gat, var der ein storvaksen mann som hadde seks fingrar på kvar hand og seks tær på kvar fot, fire og tjuge til saman. Han var ogso utstokken frå Rafa-ætti.',
        21: 'Han svivyrde Israels-mennerne. Jonatan, son åt Simea, bror åt David, gav honom difor banehugg.',
        22: 'Desse fire var ætta frå Rafa i Gat. Og dei fall for David og mennerne hans.',
    },
    22: {
        1: 'David kvad dette kvædet åt Herren då Herren hadde frelst honom frå alle uvenerne sine, og frå Saul:',
        2: '«Herren er mitt berg og mi festning og min frelsar.',
        3: 'Gud er mitt berg som eg flyr til! Min skjold og mitt frelseshorn Mi høge borg! mi livd! Frelsaren min som friar meg ifrå vald!',
        4: 'Eg kallar på Herren, den høglova: Frå fiendarne mine frelsar han meg.',
        5: 'Daudens brot og brand kringsette meg. Straumar av vondskap skræmde meg.',
        6: 'Helheims reip var snørde ikring meg. Daudsens snaror fanga meg.',
        7: 'Men Herren kalla eg på i mi trengsla, eg ropa til min Gud. Han høyrde frå templet sitt røysti mi, mitt rop rakk fram til øyro hans.',
        8: 'Jordi skok seg og skalv, himmelens grunnvollar dirra, Dei skok seg, for harmen hans loga upp:',
        9: 'Røyk steig upp frå nasen hans, eld frå munnen hans åt ikring seg, gloande kol loga frå honom.',
        10: 'Han lægde himmelen og steig ned, med kolmyrker under føterne sine.',
        11: 'Han for fram på kerub og flaug og sveiv på vengjerne åt vinden.',
        12: 'Myrkret gjorde han til åklæde kring seg, tjeldet hans var myrke vatn, tjukke skyer.',
        13: 'Frå glansen fyre andlitet hans brann gloande kol.',
        14: 'Herren tora i himmelen, den Høgste let høyra si røyst:',
        15: 'Pilerne sine skaut han og spreidde deim, eldingar sende han og fortulla deim.',
        16: 'Djupålarne i havet kom upp i dagen, grunnvollarne i jordi vart berrsynte ved Herrens trugsmål, ved andepusten frå hans nase.',
        17: 'Han rette ut handi frå høgdi og greip meg, han drog meg upp or store vatn.',
        18: 'Han frelste meg frå min megtige fiende, frå uvenern’ mine, dei var meg for sterke.',
        19: 'Dei for imot meg på motgangsdagen; men Herren vart studnaden min.',
        20: 'Han førde meg ut i vidt rom. Han frelste meg, for han hadde hugnad i meg.',
        21: 'Herren gjorde med meg etter rettferdi mi, han lønte meg etter reinleiken i henderne mine.',
        22: 'For eg tok vare på Herrens vegar, fall ikkje i vondskap frå min Gud.',
        23: 'Nei, alle hans rettar hadde eg for auga, bodordi hans veik eg ikkje ifrå.',
        24: 'So var eg ulastande for honom og tok meg i vare for mi synd.',
        25: 'Og Herren lønte meg etter mi rettferd, etter reinleiken min for hans augo.',
        26: 'Mot den godlyndte syner du deg godlyndt, mot ulastande kjempa ulastande.',
        27: 'Mot den reine syner du deg rein, mot den rangsnudde syner du deg rang.',
        28: 'For du frelsar arme folk, men augo dine er mot dei ovmodige til å tvinga deim ned.',
        29: 'For du er mi lampa, Herre, og Herren gjer myrkret mitt bjart.',
        30: 'Ved deg eg renner mot herflokkar, ved min Gud stormar eg murar.',
        31: 'Gud, ulastande er hans veg; Herrens ord er skirt, han er ein skjold for alle deim som flyr til honom.',
        32: 'For kven er Gud forutan Herren? Kven er eit berg utan vår Gud?',
        33: 'Gud, han som gyrder meg med kraft, og leider den ulastande på hans veg,',
        34: 'som gjev meg føter liksom hindarne, og set meg upp på høgderne mine,',
        35: 'som lærer henderne mine upp til strid, so armarne spenner koparbogen.',
        36: 'Du gav meg frelsa di til skjold, og småminkingi di ho gjorde meg stor.',
        37: 'Du gjorde rom for stigi mine, og oklo mine vagga ikkje.',
        38: 'Eg forfylgde fiendarne mine og tynte deim. Eg vende ikkje um fyrr eg fekk gjort ende på deim.',
        39: 'Eg gjorde ende på deim og slo deim i knas, so dei vann ikkje reisa seg. Dei fall under føterne mine.',
        40: 'Du gyrde meg med kraft til striden. Du bøygde motmennern’ mine under meg.',
        41: 'Fiendarne mine let du snu ryggen til meg, deim som hatar meg, rudde eg ut.',
        42: 'Dei såg seg um - men ingen frelste - til Herren, men han svara deim ikkje.',
        43: 'Eg smuldra deim som dust på jordi; som søyla på gator krasa eg deim; eg trakka deim ned.',
        44: 'Du frelste meg ut or mitt folks ufred, til hovud for heidningar vara du meg; folk som eg ikkje kjende, tente meg.',
        45: 'Ukjende folk smeikte for meg, ved gjetordet um meg lydde dei meg.',
        46: 'Ja, framandfolk visna av, gjekk skjelvande ut or borgerne sine.',
        47: 'Herren liver! lova vere han, mitt berg! Ja, upphøgd vere Gud, mitt frelse-berg,',
        48: 'Gud som gjev meg hemn, legg folkeslag under meg',
        49: 'og fører meg ut frå fiendarne mine! Ja - du som lyfter meg høgt yver motmennern’ mine og bergar meg undan frå valdsmanns hand!',
        50: 'Difor, Herre, vil eg prisa deg millom heidningarn’, og lovsyngja ditt namn.',
        51: 'For han gjer kongen sin sigersæl, gjer miskunn mot honom han salva, mot David og ætti hans til æveleg tid.»',
    },
    23: {
        1: 'Dette er Davids siste ord: «So lyder ordi frå David, Isaisonen, so lyder ordi frå mannen som vart upphøgd, han som Jakobs Gud hev salva, Israels ljuvlege songmeister:',
        2: 'Herrens Ande hev tala i meg, ordi hans er på tunga mi.',
        3: 'Israels Gud hev tala so, Israels berg hev sagt til meg: Den som råder og gjer rett millom menn, den som rikjer i otte for Gud;',
        4: 'han likjest på dagsprett når soli renn, ein morgon forutan skyer, når graset grønkast i sol etter regn.',
        5: 'Er det’kje so med mitt hus hjå Gud? Han gjorde ævelegt samband med meg, feste og trygde meg heilt og fullt. Ja, alt som vert meg til frelsa og gleda, det let han visseleg veksa åt meg.',
        6: 'Men uvyrdor likjest alle på utkasta tornar, ein vil ikkje taka i deim med hender.',
        7: 'Lyt ein røra deim væpnar ein seg med jarn og med spjotskaft; so set ein eld på deim og brenner deim på flekken.»',
        8: 'Dette er namni på dei djervaste stridsmennerne åt David: Joseb-Bassebet, tahkmoniten, den fremste av kjemporne, han som svinga spjotet yver åtte hundrad falne på ein gong.',
        9: 'Næst honom kom Eleazar, son åt Dodi, son åt ein ahohit. Han var ein av dei tri stridsmennerne som var med David, då filistarane samla seg til strid og svivyrde deim då Israels-mennerne drog seg attende.',
        10: 'Men han heldt stand og hogg laust på filistarane, til dess handi hans trøytna, so ho trena i hop kring sverdet. Og Herren gav ein stor siger den dagen. Etterpå hadde folket berre å snu um og fylgja med honom og plundra.',
        11: 'Næst honom kom Samma, son åt Age, ein hararit. Ein gong stemnde filistarane i hop og vart til ein heil flokk. Der var ein åkerteig full av linsor. Folket rømde for filistarane.',
        12: 'Då tok han post midt på åkerteigen og verna honom, og slo filistarane. Herren gav ein stor siger.',
        13: 'Ein gong drog tri av dei tretti fremste kararne ned, og kom i skurdonni til David i Adullams-helleren, medan ein filistarflokk låg i læger i Refa’imsdalen.',
        14: 'David var då i fjellborgi, samstundes med at ein filistarpost låg i Betlehem.',
        15: 'David fekk slik hug og sagde: «Gjev einkvan vilde gjeva meg vatn å drikka frå brunnen ved byporten i Betlehem!»',
        16: 'Då braut dei tri stridsmennerne seg gjenom filistarlægret, auste vatn or brunnen ved byporten i Betlehem og bar det til David. Men han vilde ikkje drikka det, men helte det ut for Herren.',
        17: 'For han sagde: «Aldri i verdi, Herre, vil eg gjera dette! Skulde eg drikka blodet av dei mennerne som gjekk av stad og våga livet sitt?» Og han vilde ikkje drikka det. - Sovore hadde dei tri stridsmennerne gjort.',
        18: 'Abisai, bror åt Joab Serujason, var den fremste av tri andre. Ein gong svinga han spjotet sitt yver tri hundrad falne. Han hadde eit stort namn millom dei tri;',
        19: 'han var visseleg meir vyrd enn nokon annan i dette trimannslaget; og han var hovding yver dei hine. Men upp til dei tri fyrste nådde han ikkje.',
        20: 'Benaja Jojadason var son til ein djerv og dådrik mann frå Kabse’el. Han slo dei tvo Ariel i Moab. Det var han som steig ned ein snøversdag og drap løva i brunnen.',
        21: 'Han drap og den egyptaren som var so sjåleg. Endå egyptaren hadde spjot i hand, gjekk han på honom berre med ein stav. Han reiv spjotet ut or handi på egyptaren og drap honom med hans eige spjot.',
        22: 'Sovore hadde Benaja Jojadason gjort. Han hadde eit stort namn millom dei tri stridsmennerne.',
        23: 'Han var meir vyrd enn nokon av dei tretti. Men upp til dei tri nådde han ikkje. David sette honom inn i livvakti si.',
        24: 'Til dei tretti høyrde: Asael, bror åt Joab, Elhanan Dodoson frå Betlehem,',
        25: 'Samma frå Harod, Elika frå Harod,',
        26: 'Heles, paltiten, Ira Ikkesson frå Tekoa,',
        27: 'Abiezer frå Anatot, husatiten Mebunnai,',
        28: 'ahotiten Salmon, netofatiten Maharai,',
        29: 'netofatiten Heleb Ba’anason, Ittai Ribaison frå Gibea i Benjamins-ætti,',
        30: 'Benaja, ein piratonit, Hiddai frå Ga’asdalarne,',
        31: 'arbatiten Abi-Albon, barhumiten Azmavet,',
        32: 'sa’alboniten Eljahba, Bene-Jasen, Jonatan,',
        33: 'harariten Samma, arariten Ahiam Sararsson,',
        34: 'Elifelet, son åt Ahasbai, son åt ma’akatiten, Eliam Ahitofelsson frå Gilo,',
        35: 'Hesro frå Karmel, arbiten Pa’arai,',
        36: 'Jigal Natansson frå Soba, gaditen Bani,',
        37: 'ammoniten Selek, be’erotiten Naharai, våpnsveinen åt Joab Serujason,',
        38: 'jitriten Ir, jitriten Gareb,',
        39: 'hetiten Uria. I alt var dei sju og tretti.',
    },
    24: {
        1: 'Herrens harm loga upp mot Israel att, so eggja David mot deim og sagde: «Gakk av stad og tel Israel og Juda!»',
        2: 'Då baud kongen Joab, herhovdingen som var hjå honom: «Far gjenom alle ættarne i Israel frå Dan alt til Be’erseba og mynstra folket, so eg kann få vita folketalet!',
        3: 'Joab svara kongen: «Gjev Herren, din Gud, må gjera dette folket hundrad gonger so talrikt som det er! Og gjev du, herre konge, må få sjå det med eigne augo! Men kvifor hev du, herre konge, fenge hug på sovore?»',
        4: 'Like ved stod kongsbodet fast. Joab og dei hine herhovdingarne laut lyda. Joab og dei hine herhovdingarne drog då ut i kongens ærend og mynstra Israels-folket.',
        5: 'Dei gjekk yver Jordan og slo lægra seg ved Aroer på høgre sida av byen, i Gadsdalen burtimot Jazer.',
        6: 'Derifrå kom dei til Gilead og Tatim-Hodsilandet. So kom dei til Dan-Ja’an, og so rundt ikring til Sidon.',
        7: 'Deretter kom dei til festningi i Tyrus og alle hevitarbyarne og kananitarbyarne. Til slutt drog dei til Be’erseba i Juda-sudlandet.',
        8: 'Då dei hadde fare soleis gjenom heile landet, kom dei heim til Jerusalem. Ferdi hadde teke ni månader og tjuge dagar.',
        9: 'Joab gav upp åt kongen heile talet som folketeljingi synte: Israel åtte hundrad tusund fullgode våpnføre stridsmenner, og Juda-folki fem hundrad tusund.',
        10: 'Men David fekk samvitsagg etter han hadde talt folket. Og David sagde til Herren: «Eg hev synda grovt med det eg hev gjort. Men tilgjev no, Herre, illgjerdi åt tenaren din! for det var mykje uvisleg gjort av meg.»',
        11: 'Då David reis upp um morgonen, var Herrens ord kome til profeten Gad, sjåaren åt David. Han hadde sagt:',
        12: 'Gakk og seg med David: «So segjer Herren: Tri ting legg eg fram for deg; vel ein av deim som du vil eg skal gjera med deg!»»',
        13: 'Gad gjekk inn til David og forkynte honom dette. Han spurde honom: «Vil du at det skal koma sju store uår i landet ditt? Eller vil du i tri månader ljota røma for uvenerne dine med dei forfylgjer deg? Eller at eg skal søkja landet ditt med drepsott i tri dagar? Tenk no yver det, og sjå til kva svar eg skal gjeva honom som hev sendt meg!»',
        14: 'David svara Gad: «Eg er i stor vande. Men lat oss då falla i Herrens hand! for hans miskunn er stor. I menneskjehand vil eg ikkje falla.»',
        15: 'So søkte Herren Israel med drepsott frå morgonen til den fastsette tidi. Sju og sytti tusund mann døydde av folket frå Dan til Be’erseba.',
        16: 'Men då engelen rette ut handi yver Jerusalem og vilde tyna det, so angra Herren det vonde. Og han sagde til engelen som tynte folket: «Det er nok! Drag no handi di attende!» Og Herrens engel var då ved treskjarvollen åt jebusiten Aravna.',
        17: 'Men då David fekk sjå engelen som herja millom folket, tala han so til Herren: «Det er då eg som hev synda, det er eg som hev fare gale! men desse sauerne - kva hev dei gjort? Gjev handi di må venda seg mot meg og farshuset mitt!»',
        18: 'Og Gad kom til David same dagen og sagde til honom: «Gakk av stad og reis eit altar åt Herren på treskjarvollen åt jebusiten Aravna!»',
        19: 'David gjekk av stad etter Gads ord, so som Herren hadde bode honom.',
        20: 'Då Aravna skoda ut og fekk sjå kongen og kongstenarane koma til honom, gjekk han ut og fall å gruve til jordi framfor kongen.',
        21: 'Aravna spurde: «Kvifor kjem du, herre konge, til tenaren din?» David svara: «Eg vil kjøpa treskjarvollen av deg og byggja der eit altar åt Herren, so sotti må stana som hev herja folket.»',
        22: 'Då sagde Aravna med David: «Tak du og ofra kva du tykkjer høvlegast, herre konge! Her er fe til brennoffer. Her er treskjarvogni og oket på feet til ved.',
        23: 'Alt saman, konge, gjev Aravna kongen.» Og Aravna lagde til: «Gjev Herren, din Gud, må hava hugnad i deg!»',
        24: 'Kongen svara Aravna: «Nei, eg vil kjøpa det av deg for full pris. Eg vil ikkje ofra åt Herren, min Gud, brennoffer som ingen ting kostar.» So kjøpte David treskjarvollen og feet for femti sylvdalar.',
        25: 'David bygde der eit altar åt Herren, og ofra brennoffer og takkoffer. Då bønhøyrde Herren landet. Og då stana sotti som hadde herja Israel.',
    },
}
